Object.assign(window.TEM8_DICTIONARY, {"impressive":{"media":{"uk":"media/uk/impressive__gb_1.mp3","us":"media/us/impressive__us_1.mp3"},"oxford":{"phon":"ɪmˈpresɪv","pos":"adjective","senses":[{"en":"making you admire them, because they are very large, good, skilful, etc.","cn":"令人赞叹的；令人敬佩的","ex":{"en":"an impressive performance","cn":"令人赞叹的演出"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"给人深刻印象的;不俗的;了不起的","en":"Something that is impressive impresses you, for example because it is great in size or degree, or is done with a great deal of skill.","ex":{"en":"It is an impressive achievement","cn":"那是一项了不起的成就。"}}]},"examples":[{"en":"one of the most impressive novels of recent years","cn":"近年来给人印象最深的小说之一"},{"en":"She was very impressive in the interview.","cn":"她在面试中表现得十分出色。"}]},"imposing":{"media":{"uk":"media/uk/imposing__gb_1.mp3","us":"media/us/imposing__us_1.mp3"},"oxford":{"phon":"ɪmˈpəʊzɪŋ","pos":"adjective","senses":[{"en":"impressive to look at; making a strong impression","cn":"壮观的；使人印象深刻的","ex":{"en":"a grand and imposing building","cn":"雄伟壮观的建筑物"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人难忘的;仪表堂堂的;壮观的","en":"If you describe someone or something as imposing, you mean that they have an impressive appearance or manner.","ex":{"en":"He was an imposing man.","cn":"他仪表堂堂。"}}]},"examples":[{"en":"a grand and imposing building","cn":"雄伟壮观的建筑物"},{"en":"a tall imposing woman","cn":"高大壮硕的女人"}]},"impact":{"media":{"uk":"media/uk/impact__gb_1.mp3","us":"media/us/impact__us_1.mp3"},"oxford":{"phon":"ˈɪmpækt","pos":"noun","senses":[{"en":"the powerful effect that something has on somebody/something","cn":"巨大影响；强大作用","ex":{"en":"a positive/a negative/an adverse impact","cn":"好的／不好的影响"}},{"en":"the act of one object hitting another; the force with which this happens","cn":"撞击；冲撞；冲击力","ex":{"en":"craters made by meteorite impacts","cn":"陨石撞击而成的陨石坑"}},{"en":"to have an effect on somebody/something","cn":"（对人或事物）有影响，有作用","g":"[intransitive, transitive]","ex":{"en":"Her father's death impacted greatly on her childhood years.","cn":"父亲去世对她的童年造成巨大影响。"},"pos":"verb"},{"en":"to hit something with great force","cn":"冲击；撞击","g":"[intransitive, transitive]","lab":"formal","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"影响;作用","en":"The impact that something has on a situation, process, or person is a sudden and powerful effect that it has on them.","ex":{"en":"They say they expect the meeting to have a marked impact on the future of the country","cn":"他们称他们预期会议对国家的未来会产生显著影响。"}},{"pos":"N-VAR 可变名词","cn":"撞击;碰撞;撞击力","en":"An impact is the action of one object hitting another, or the force with which one object hits another.","ex":{"en":"The plane is destroyed, a complete wreck: the pilot must have died on impact","cn":"飞机遭到毁坏,完全成了一堆残骸：飞行员肯定死于撞击。"}},{"pos":"VERB 动词","cn":"(对…)产生影响","en":"To impact on a situation, process, or person means to affect them.","ex":{"en":"Such schemes mean little unless they impact on people.","cn":"这些计划没什么意义,除非它们对人民产生影响。"}},{"pos":"VERB 动词","cn":"撞击;冲击;碰撞","en":"If one object impacts on another, it hits it with great force.","ex":{"en":"...the sharp tinkle of metal impacting on stone","cn":"金属撞击石头发出的刺耳叮当声"}}]},"examples":[{"en":"The report assesses the impact of AIDS on the gay community.","cn":"这个报告评估了艾滋病对同性恋群体的影响。"},{"en":"Businesses are beginning to feel the full impact of the recession.","cn":"工商企业开始感受到了经济衰退的全面冲击。"}]},"imprisonment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"关押;监禁;坐牢","en":"Imprisonment is the state of being imprisoned.","ex":{"en":"She was sentenced to seven years' imprisonment.","cn":"她被判处 7 年监禁。"}}]},"media":{"uk":"media/uk/imprisonment__gb_1.mp3","us":"media/us/imprisonment__us_1.mp3"},"examples":[{"en":"to be sentenced to life imprisonment for murder","cn":"因犯谋杀罪被判终身监禁"},{"en":"They were sentenced to 6 years’ imprisonment.","cn":"他们被判处六年监禁。"}],"oxford":{"phon":"ɪmˈprɪznmənt","pos":"noun","senses":[{"en":"the act of putting somebody in a prison or another place from which they cannot escape; the state of being there","cn":"监禁；关押","ex":{"en":"to be sentenced to life imprisonment for murder","cn":"因谋杀罪被判终身监禁"}}]}},"imaginary":{"oxford":{"phon":"ɪˈmædʒɪnəri","pos":"adjective","senses":[{"en":"existing only in your mind or imagination","cn":"想象中的；幻想的；虚构的","ex":{"en":"The equator is an imaginary line around the middle of the earth.","cn":"赤道是一条环绕地球中部的假想线。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"想象中的;假想的;虚构的","en":"An imaginary person, place, or thing exists only in your mind or in a story, and not in real life.","ex":{"en":"Lots of children have imaginary friends.","cn":"许多孩子都会凭空想象一些朋友。"}}]},"media":{"uk":"media/uk/imaginary__gb_1.mp3","us":"media/us/imaginary__us_1.mp3"},"examples":[{"en":"The equator is an imaginary line around the middle of the earth.","cn":"赤道是一条假想的环绕地球腰部的线。"},{"en":"imaginary fears","cn":"想像中的恐惧"}]},"impatient":{"media":{"uk":"media/uk/impatient__gb_1.mp3","us":"media/us/impatient__us_1.mp3"},"oxford":{"phon":"ɪmˈpeɪʃnt","pos":"adjective","senses":[{"en":"annoyed by somebody/something, especially because you have to wait for a long time","cn":"不耐烦的；没有耐心的","ex":{"en":"I'd been waiting for twenty minutes and I was getting impatient.","cn":"我等了二十分钟，有点不耐烦了。"}},{"en":"wanting to do something soon; wanting something to happen soon","cn":"急于；热切期待","ex":{"en":"She was clearly impatient to leave.","cn":"她显然是迫不及待地想离开。"}},{"en":"unable or unwilling to accept something unpleasant","cn":"（对不愉快的事）不能容忍，不愿接受","lab":"formal","ex":{"en":"impatient of criticism","cn":"不愿接受批评"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不耐烦的;急躁的","en":"If you are impatient, you are annoyed because you have to wait too long for something.","ex":{"en":"He is impatient as the first hour passes and then another","cn":"一个小时、两个小时过去了,他不耐烦了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易发火的;无耐心的","en":"If you are impatient, you are easily irritated by things.","ex":{"en":"Beware of being too impatient with others","cn":"注意不要对人不耐烦。"}},{"pos":"ADJ 形容词","cn":"迫不及待的;切望的;急不可耐的","en":"If you are impatient to do something or impatient for something to happen, you are eager to do it or for it to happen and do not want to wait.","ex":{"en":"He was impatient to get home","cn":"他迫不及待想要回家。"}}]},"examples":[{"en":"Sarah was becoming increasingly impatient at their lack of interest.","cn":"萨拉对他们的缺乏兴趣的情况越来越不能忍耐了。"},{"en":"I'd been waiting for twenty minutes and I was getting impatient.","cn":"我等了二十分钟，有点不耐烦了。"}]},"importance":{"media":{"uk":"media/uk/importance__gb_1.mp3","us":"media/us/importance__us_1.mp3"},"oxford":{"phon":"ɪmˈpɔːtns","pos":"noun","senses":[{"en":"the quality of being important","cn":"重要性；重要；重大","ex":{"en":"She stressed the importance of careful preparation.","cn":"她强调了认真准备的重要性。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"重要;重大;重要性","en":"The importance of something is its quality of being significant, valued, or necessary in a particular situation.","ex":{"en":"We have always stressed the importance of economic reform","cn":"我们一向强调经济改革的重要性。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"重要地位;名望","en":"Importance means having influence, power, or status."}]},"examples":[{"en":"She stressed the importance of careful preparation.","cn":"她强调了认真准备的重要性。"},{"en":"It's a matter of the greatest importance to me.","cn":"这对我来说是最重要的事情。"}]},"impersonally":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel as though you are not wanted","cn":""},{"en":"unfriendly – used especially about the physical characteristics or appearance of something","cn":""}]},"examples":[{"en":"Business letters do not have to be impersonal and formal.","cn":"","src":"ld"},{"en":"Sometimes she seems a very impersonal, even unkind, mother.","cn":"","src":"ld"}],"media":{"uk":"media/uk/impersonally__gb_1.mp3","us":"media/us/impersonally__us_1.mp3"},"oxford":{"phon":"ɪmˈpɜːsənəli","pos":"adverb","senses":[{"en":"in a way that lacks friendly human feelings or atmosphere and may make you feel unimportant","cn":"缺乏人情味的；冷淡的","lab":"usually disapproving","ex":{"en":"He treated her coldly and impersonally, like a stranger.","cn":"他对待她冷漠无情，就像对待陌生人一样。"}},{"en":"in a way that does not refer to any particular person; in a way that is not concerned with people as individuals","cn":"客观地：以不涉及任何特定人的方式；以与个人无关的方式","ex":{"en":"The doctors learn to look at patients impersonally.","cn":"医生学会客观地看待病人。"}},{"en":"using ‘it’ or ‘there’ as the subject","cn":"客观地：以“它”或“那里”为主题","lab":"grammar","ex":{"en":"Some verbs can be used impersonally.","cn":"有些动词可以非人称地使用。"}}]}},"impulsively":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you do something rash , you do not think carefully about the effect it will have, and you wish later you had not done it","cn":""},{"en":"too quick to do or say something, without taking time to think about it first","cn":""}]},"examples":[{"en":"Rosa was impulsive and sometimes regretted things she’d done.","cn":"","src":"ld"},{"en":"In a burst of impulsive generosity, I offered to pay.","cn":"","src":"ld"}],"media":{"uk":"media/uk/impulsively__gb_1.mp3","us":"media/us/impulsively__us_1.mp3"},"oxford":{"phon":"ɪmˈpʌlsɪvli","pos":"adverb","senses":[{"en":"suddenly, without thinking carefully about what might happen because of what you are doing","cn":"凭冲动行事的；易冲动的","ex":{"en":"Impulsively he reached out and took her hand.","cn":"他一时冲动，伸手握住了她的手。"}}]}},"improvise":{"media":{"uk":"media/uk/improvise__gb_1.mp3","us":"media/us/improvise__us_1.mp3"},"oxford":{"phon":"ˈɪmprəvaɪz","pos":"verb","senses":[{"en":"to make or do something using whatever is available, usually because you do not have what you really need","cn":"临时拼凑；临时做","g":"[intransitive, transitive]","ex":{"en":"There isn't much equipment. We're going to have to improvise.","cn":"设备不多，我们只能将就着用。"}},{"en":"to invent music, the words in a play, a statement, etc. while you are playing or speaking, instead of planning it in advance","cn":"即兴创作（音乐、台词、演讲词等）","g":"[intransitive, transitive]","ex":{"en":"‘It'll be ready some time next week, I expect,’ she said, improvising.","cn":"“我估计下个星期内会准备好的。”她随口说道。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"临时做;临时凑成","en":"If you improvise, you make or do something using whatever you have or without having planned it in advance.","ex":{"en":"You need a wok with a steaming rack for this; if you don't have one, improvise","cn":"要做这个，你需要一口带蒸笼篦子的锅,如果没有,就用别的临时凑合一下。"}},{"pos":"VERB 动词","cn":"即兴表演;即兴演奏;即兴创作","en":"When performers improvise, they invent music or words as they play, sing, or speak.","ex":{"en":"I asked her what the piece was and she said, 'Oh, I'm just improvising'","cn":"我问她那一段是什么音乐,她说：“噢,我只是即兴弹的。”"}}]},"examples":[{"en":"‘It'll be ready some time next week, I expect,’ she said, improvising. “","cn":"我估计下个星期内会准备好的。”她随口说道。"},{"en":"We improvised some shelves out of planks of wood and bricks.","cn":"我们用木板和砖头临时搭了些架子。"}]},"imprint":{"media":{"uk":"media/uk/imprint__gb_1.mp3","us":"media/us/imprint__us_1.mp3"},"oxford":{"phon":"ɪmˈprɪnt","pos":"verb","senses":[{"en":"to have a great effect on something so that it cannot be forgotten, changed, etc.","cn":"产生重大影响；铭刻；使铭记","ex":{"en":"The terrible scenes were indelibly imprinted on his mind.","cn":"那些恐怖场面深深地铭刻在他的心中。"}},{"en":"to print or press a mark or design onto a surface","cn":"印；压印","ex":{"en":"Their footprints were imprinted in the snow.","cn":"他们的脚印印在雪地里。"}},{"en":"a mark made by pressing something onto a surface","cn":"印记；压印；痕迹","ex":{"en":"the imprint of a foot in the sand","cn":"沙滩上的足迹"},"pos":"noun"},{"en":"the lasting effect that a person or an experience has on a place or a situation","cn":"持久影响","g":"[usually singular]","lab":"formal","ex":{"en":"Colonialism has left an indelible imprint on the island.","cn":"殖民主义在岛上留下了不可磨灭的印记。"},"pos":"noun"},{"en":"the name of the publisher of a book, usually printed below the title on the first page; a brand name under which books are published","cn":"出版商名称（通常印在第一页的书名下面）","lab":"specialist","ex":{"en":"They publish under several imprints.","cn":"他们以几个出版商标识出版。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"印记;深远影响","en":"If something leaves an imprint on a place or on your mind, it has a strong and lasting effect on it.","ex":{"en":"The city bears the imprint of Japanese investment","cn":"该市带有日本投资的深刻印记。"}},{"pos":"VERB 动词","cn":"铭刻;使牢记","en":"When something is imprinted on your memory, it is firmly fixed in your memory so that you will not forget it.","ex":{"en":"The skyline of domes and minarets was imprinted on my memory","cn":"天空中穹顶与尖塔的轮廓深深刻在了我的记忆中。"}},{"pos":"N-COUNT 可数名词","cn":"印痕;痕迹","en":"An imprint is a mark or outline made by the pressure of one object on another.","ex":{"en":"The ground still bore the imprints of their feet.","cn":"地面上仍然留有他们的脚印。"}},{"pos":"VERB 动词","cn":"印;压印","en":"If a surface is imprinted with a mark or design, that mark or design is printed on the surface or pressed into it.","ex":{"en":"Stationery can be imprinted with your message or logo","cn":"可以把你的信息或标志印在信纸上。"}}]},"examples":[{"en":"The terrible scenes were indelibly imprinted on his mind.","cn":"那些恐怖场面深深地铭刻在他的心中。"},{"en":"clothes imprinted with the logos of sports teams","cn":"印着运动队标志的衣服"}]},"impossible":{"media":{"uk":"media/uk/impossible__gb_1.mp3","us":"media/us/impossible__us_1.mp3"},"oxford":{"phon":"ɪmˈpɒsəbl","pos":"adjective","senses":[{"en":"that cannot exist or be done; not possible","cn":"不可能存在（或做到）的；不可能的","ex":{"en":"almost/virtually/nearly impossible","cn":"几乎不可能"}},{"en":"very difficult to deal with","cn":"很难对付（或处理）的","ex":{"en":"I've been placed in an impossible position.","cn":"我陷入了进退维谷的境地。"}},{"en":"a thing that is or seems impossible","cn":"（似乎）不可能的事","g":"[singular]","ex":{"en":"to attempt the impossible","cn":"明知不可为而为之"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不可能的;做不到的","en":"Something that is impossible cannot be done or cannot happen.","ex":{"en":"It was impossible for anyone to get in because no one knew the password","cn":"因为没人知道密码,所以任何人都不可能进得去。"}},{"pos":"ADJ 形容词","cn":"极难应付的","en":"An impossible situation or an impossible position is one that is very difficult to deal with.","ex":{"en":"The Government was now in an almost impossible position.","cn":"政府现在几乎陷入了进退维谷的境地。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以忍受的;让人受不了的","en":"If you describe someone as impossible, you are annoyed that their bad behaviour or strong views make them difficult to deal with.","ex":{"en":"The woman is impossible, thought Frannie.","cn":"弗兰妮想,这个女人真让人受不了。"}}]},"examples":[{"en":"Honestly, you're impossible at times!","cn":"说实话，你有时真令人难以忍受。"},{"en":"the sheer impossibility of providing enough food for everyone","cn":"完全无法给每个人提供足够的食物"}]},"immediately":{"media":{"uk":"media/uk/immediately__gb_1.mp3","us":"media/us/immediately__us_1.mp3"},"oxford":{"phon":"ɪˈmiːdiətli","pos":"adverb","senses":[{"en":"without delay","cn":"立即；马上；即刻","ex":{"en":"She answered almost immediately.","cn":"她几乎立刻就回答了。"}},{"en":"next to or very close to a particular place or time","cn":"接近；紧接；附近","ex":{"en":"Turn right immediately after the church.","cn":"一过教堂就向右拐。"}},{"en":"closely and directly","cn":"紧接地；直接地","ex":{"en":"Counselling is being given to those most immediately affected by the tragedy.","cn":"目前正在向惨剧的最直接受害者提供辅导服务。"}},{"en":"as soon as","cn":"一…就…","ex":{"en":"Immediately she'd gone, I remembered her name.","cn":"她刚走开我就想起了她的名字。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"立即;马上","en":"If something happens immediately, it happens without any delay.","ex":{"en":"He immediately flung himself to the floor","cn":"他立即飞身扑到地上。"}},{"pos":"ADV 副词","cn":"即刻(可见或明了的)","en":"If something is immediately obvious, it can be seen or understood without any delay.","ex":{"en":"The cause of the accident was not immediately apparent.","cn":"事故的起因并非一目了然。"}},{"pos":"ADV 副词","cn":"直接地","en":"Immediately is used to indicate that someone or something is closely and directly involved in a situation.","ex":{"en":"The man immediately responsible for this misery is the province's governor","cn":"对这种不幸境况负有直接责任的人是该省的省长。"}},{"pos":"ADV 副词","cn":"紧接地;紧靠地;贴近地","en":"Immediately is used to emphasize that something comes next, or is next to something else.","ex":{"en":"They wish to begin immediately after dinner","cn":"他们希望饭后马上就开始。"}},{"pos":"CONJ-SUBORD 连词","cn":"一…(就…)","en":"If one thing happens immediately something else happens, it happens after that event, without any delay.","ex":{"en":"Immediately I've done it I feel completely disgusted with myself.","cn":"我一做完那件事就对自己感到十分厌恶。"}}]},"examples":[{"en":"The point of my question may not be immediately apparent.","cn":"我的问题的要点可能不是一下子就能看出来的。"},{"en":"Counselling is being given to those most immediately affected by the tragedy.","cn":"目前正在向惨剧的最直接受害者提供辅导服务。"}]},"imperiously":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"giving orders and expecting to be obeyed, in a way that seems too proud","cn":""}]},"examples":[{"en":"She raised her hand in an imperious gesture.","cn":"","src":"ld"}],"media":{"uk":"media/uk/imperiously__gb_1.mp3","us":"media/us/imperiously__us_1.mp3"},"oxford":{"phon":"ɪmˈpɪəriəsli","pos":"adverb","senses":[{"en":"in a way that shows you expect people to obey you and treats them as if they are not as important as you","cn":"专横的；蛮横的；盛气凌人的","ex":{"en":"‘Get it now,’ she demanded imperiously.","cn":"“现在就给我拿来。”她蛮横地要求道。"}}]}},"imagination":{"media":{"uk":"media/uk/imagination__gb_1.mp3","us":"media/us/imagination__us_1.mp3"},"oxford":{"phon":"ɪˌmædʒɪˈneɪʃn","pos":"noun","senses":[{"en":"the ability to create pictures in your mind; the part of your mind that does this","cn":"想象力；想象","g":"[uncountable, countable]","lab":"informal","ex":{"en":"a vivid/fertile imagination","cn":"生动的／丰富的想象"}},{"en":"something that you have imagined rather than something that exists","cn":"想象的事物；幻想物","g":"[uncountable]","ex":{"en":"She was no longer able to distinguish between imagination and reality.","cn":"她再也分不清幻想和现实了。"}},{"en":"the ability to have new and exciting ideas","cn":"创造力；创作力","g":"[uncountable]","lab":"approving","ex":{"en":"His writing lacks imagination.","cn":"他写的东西缺乏想象。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"想象;想象力","en":"Your imagination is the ability that you have to form pictures or ideas in your mind of things that are new and exciting, or things that you have not experienced.","ex":{"en":"Antonia is a woman with a vivid imagination","cn":"安东尼娅是个想象力丰富的女人。"}},{"pos":"N-COUNT 可数名词","cn":"想象；空想；幻想","en":"Your imagination is the part of your mind which allows you to form pictures or ideas of things that do not necessarily exist in real life.","ex":{"en":"Long before I ever went there, Africa was alive in my imagination.","cn":"早在我真正踏足之前很久,非洲就已在我的脑海中活灵活现了。"}},{"pos":"PHRASE 短语","cn":"吸引…的注意力;摄人魂魄;引人入胜","en":"If you say that someone or something captured your imagination, you mean that you thought they were interesting or exciting when you saw them or heard them for the first time.","ex":{"en":"Italian football captured the imagination of the nation last season.","cn":"上个赛季意大利足球吸引了全国上下的注意。"}},{"pos":"PHRASE 短语","cn":"发人深省;予人启迪","en":"If you say that something stretches your imagination, you mean that it is good because it makes you think about things that you had not thought about before.","ex":{"en":"Their films are exciting and really stretch the imagination.","cn":"他们的电影非常精彩且发人深省。"}},{"pos":"","cn":"","en":"not by any stretch of the imagination→see: ;"}]},"examples":[{"en":"With a little imagination, you could turn this place into a palace.","cn":"稍微动点脑筋，就能把这个地方变得富丽堂皇。"},{"en":"The new policies appear to have caught the imagination of the public (= they find them interesting and exciting).","cn":"新出台的政策似乎恰恰投合了公众的喜好。"}]},"impulse":{"media":{"uk":"media/uk/impulse__gb_1.mp3","us":"media/us/impulse__us_1.mp3"},"oxford":{"phon":"ˈɪmpʌls","pos":"noun","senses":[{"en":"a sudden strong wish or need to do something, without stopping to think about the results","cn":"冲动；心血来潮；一时的念头","g":"[countable, usually singular, uncountable]","ex":{"en":"He had a sudden impulse to stand up and sing.","cn":"他突然心血来潮，想站起来唱歌。"}},{"en":"a force or movement of energy that causes something else to react","cn":"动力；冲力；冲量","g":"[countable]","lab":"specialist","ex":{"en":"nerve/electrical impulses","cn":"神经冲动；电路脉冲"}},{"en":"something that causes somebody/something to do something or to develop and make progress","cn":"推动力；刺激","g":"[countable, usually singular, uncountable]","lab":"formal","ex":{"en":"to give an impulse to the struggling car industry","cn":"给予挣扎中的汽车工业一点刺激"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"冲动;一时兴起的念头","en":"An impulse is a sudden desire to do something.","ex":{"en":"Unable to resist the impulse, he glanced at the sea again","cn":"他抑制不住冲动,又向海面瞥了一眼。"}},{"pos":"N-COUNT 可数名词","cn":"脉冲","en":"An impulse is a short electrical signal that is sent along a wire or nerve or through the air, usually as one of a series."},{"pos":"ADJ 形容词","cn":"一时兴起的;随兴的","en":"An impulse buy or impulse purchase is something that you decide to buy when you see it, although you had not planned to buy it.","ex":{"en":"The curtains were an impulse buy.","cn":"窗帘是一时兴起买下的。"}},{"pos":"PHRASE 短语","cn":"凭冲动;一时兴起","en":"If you do something on impulse, you suddenly decide to do it, without planning it.","ex":{"en":"Sean's a fast thinker, and he acts on impulse","cn":"肖恩是个思维敏捷、行事随兴的人。"}}]},"examples":[{"en":"The door was open and on (an) impulse she went inside.","cn":"门开着，她一时心血来潮就走了进去。"},{"en":"He had a sudden impulse to stand up and sing.","cn":"他突然心血来潮，想站起来歌唱。"}]},"impresses":{"oxford":{"phon":"ɪmˈpres","pos":"verb","senses":[{"en":"if a person or thing impresses you, you feel admiration for them or it","cn":"使钦佩；使敬仰；给 … 留下深刻的好印象"},{"en":"( formal ) to make sb understand how important, serious, etc. sth is by emphasizing it","cn":"使意识到（重要性或严肃性等）"}]}},"implemented":{"oxford":{"phon":"ˈɪmplɪment","pos":"verb","senses":[{"en":"( formal ) to make sth that has been officially decided start to happen or be used","cn":"使生效；贯彻；执行；实施"},{"en":"( formal ) a tool or an instrument, often one that is quite simple and that is used outdoors","cn":"工具，器具（常指简单的户外用具）"}]}},"imagery":{"media":{"uk":"media/uk/imagery__gb_1.mp3","us":"media/us/imagery__us_1.mp3"},"oxford":{"phon":"ˈɪmɪdʒəri","pos":"noun","senses":[{"en":"language that produces pictures in the minds of people reading or listening","cn":"形象的描述；意象","lab":"US English","ex":{"en":"poetic imagery","cn":"诗的意象"}},{"en":"pictures, photographs, etc.","cn":"像；画像；照片","lab":"formal","ex":{"en":"satellite imagery (= for example, photographs of the earth taken from space)","cn":"卫星影像（如从太空拍摄地球的照片）"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"意象;形象化描述","en":"You can refer to the descriptions in something such as a poem or song, and the pictures they create in your mind, as its imagery .","ex":{"en":"...the nature imagery of the ballad.","cn":"民歌中的自然意象"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指具有象征意义的)图片,意象,形象","en":"You can refer to pictures and representations of things as imagery, especially when they act as symbols.","ex":{"en":"This is an ambitious and intriguing movie, full of striking imagery.","cn":"这是一部气势恢宏、引人入胜的电影,充满了动人心魄的瑰丽意象。"}}]},"examples":[{"en":"satellite imagery (= for example, photographs of the earth taken from space)","cn":"卫星影像（如从太空拍摄地球的照片）"},{"en":"poetic imagery","cn":"诗的意象"}]},"imaginable":{"media":{"uk":"media/uk/imaginable__gb_1.mp3","us":"media/us/imaginable__us_1.mp3"},"oxford":{"phon":"ɪˈmædʒɪnəbl","pos":"adjective","senses":[{"en":"used with superlatives, and with all and every, to emphasize that something is the best, worst, etc. that you can imagine, or includes every possible example","cn":"（与形容词最高级或与 all、every 连用，表示强调或概括）想象得到的","ex":{"en":"The house has the most spectacular views imaginable.","cn":"从这所房子可以看到所能想象的最壮丽的景色。"}},{"en":"possible to imagine","cn":"可想象的","ex":{"en":"These technological developments were hardly imaginable 30 years ago.","cn":"这些科技新产品在 30 年前几乎是不可想象的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(常与 best，worst 等形容词最高级连用)可想象的,想得到的","en":"You use imaginable after a superlative such as 'best' or 'worst' to emphasize that something is extreme in some way.","ex":{"en":"...their imprisonment under some of the most horrible circumstances imaginable","cn":"他们被关押在可以想象出的最恐怖的环境中"}},{"pos":"ADJ 形容词","cn":"(用于 every，all 之后，表示强调)(一切)可能存在的,(一切)可能发生的;(用于 no 以后)根本","en":"You use imaginable after a word like 'every' or 'all' to emphasize that you are talking about all the possible examples of something. You use imaginable after 'no' to emphasize that something does not have the quality mentioned.","ex":{"en":"...all of the other imaginable ramifications of this technology","cn":"这项技术可能产生的其他一切后果"}}]},"examples":[{"en":"These technological developments were hardly imaginable 30 years ago.","cn":"这些科技新产品在 30 年前几乎是不可想像的。"},{"en":"The house has the most spectacular views imaginable.","cn":"从这所房子可以看到所能想像的最壮丽的景色。"}]},"immediate":{"media":{"uk":"media/uk/immediate__gb_1.mp3","us":"media/us/immediate__us_1.mp3"},"oxford":{"phon":"ɪˈmiːdiət","pos":"adjective","senses":[{"en":"happening or done without delay","cn":"立即的；立刻的","ex":{"en":"an immediate reaction/response","cn":"即时的反应／回应"}},{"en":"existing now and needing attention quickly","cn":"目前的；当前的；迫切的","g":"[usually before noun]","ex":{"en":"Our immediate concern is to help the families of those who died.","cn":"我们的当务之急是帮助那些死者的亲属。"}},{"en":"next to or very close to a particular place or time","cn":"接近的；紧接的；附近的","g":"[only before noun]","ex":{"en":"in the immediate vicinity","cn":"近在咫尺"}},{"en":"nearest in relationship or rank","cn":"（关系或级别）最接近的，直系的，直接的","g":"[only before noun]","ex":{"en":"The funeral was attended by her immediate family (= her parents, children, brothers and sisters) only.","cn":"只有她的直系亲属参加了葬礼。"}},{"en":"having a direct effect","cn":"（作用）直接的","g":"[only before noun]","ex":{"en":"The immediate cause of death is unknown.","cn":"造成死亡的直接原因不明。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"立即的;即刻的;即时的","en":"An immediate result, action, or reaction happens or is done without any delay.","ex":{"en":"These tragic incidents have had an immediate effect","cn":"这些悲剧性事件造成的后果即刻显现。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"急迫的;紧急的","en":"Immediate needs and concerns exist at the present time and must be dealt with quickly.","ex":{"en":"Relief agencies say the immediate problem is not a lack of food, but transportation.","cn":"救援机构称最紧迫的问题不是食物匮乏,而是运输不畅。"}},{"pos":"ADJ 形容词","cn":"最接近的;紧接的","en":"The immediate person or thing comes just before or just after another person or thing in a sequence.","ex":{"en":"In the immediate aftermath of the riots, a mood of hope and reconciliation sprang up","cn":"暴乱过后紧接着出现了期待未来与盼望和解的气氛。"}},{"pos":"ADJ 形容词","cn":"临近的;贴近的","en":"You use immediate to describe an area or position that is next to or very near a particular place or person.","ex":{"en":"Only a handful had returned to work in the immediate vicinity","cn":"仅有几个人回到临近地区工作。"}},{"pos":"ADJ 形容词","cn":"直系的","en":"Your immediate family are the members of your family who are most closely related to you, for example your parents, children, brothers, and sisters.","ex":{"en":"The presence of his immediate family is obviously having a calming effect on him.","cn":"他的直系亲属都在场,这显然起到了让他镇定的作用。"}}]},"examples":[{"en":"The effects of global warming, while not immediate, are potentially catastrophic.","cn":"全球气温上升的后果虽然并非即时发生，但可能潜伏着大灾难。"},{"en":"Our immediate concern is to help the families of those who died.","cn":"我们的当务之急是帮助那些死者的亲属。"}]},"impressed":{"media":{"uk":"media/uk/impressed__gb_1.mp3","us":"media/us/impressed__us_1.mp3"},"oxford":{"phon":"ɪmˈprest","pos":"adjective","senses":[{"en":"admiring somebody/something because you think they are particularly good, interesting, etc.","cn":"（对…）赞叹，钦佩，有深刻的好印象","ex":{"en":"I must admit I am impressed.","cn":"我得承认我很佩服。"}}]},"examples":[{"en":"She was suitably impressed (= as impressed as sb had hoped) with the painting.","cn":"果然不出所料，她对那幅油画产生了兴趣。"},{"en":"We were all impressed by her enthusiasm.","cn":"我们都被她的热情打动了。"}]},"impressions":{"oxford":{"phon":"ɪmˈpreʃn","pos":"noun","senses":[{"en":"an idea, a feeling or an opinion that you get about sb/sth, or that sb/sth gives you","cn":"印象；感想"},{"en":"the effect that an experience or a person has on sb/sth","cn":"影响；效果"}]},"media":{"uk":"media/uk/impression__gb_1.mp3","us":"media/us/impression__us_1.mp3"}},"importantly":{"oxford":{"phon":"ɪmˈpɔːtntli","pos":"adverb","senses":[{"en":"used for saying that something is important","cn":"重要的是","ex":{"en":"More importantly, can he be trusted?","cn":"更重要的是，他值得信任吗？"}},{"en":"in a way that shows that somebody has, or seems to have, great influence or authority","cn":"影响很大地；权威地","ex":{"en":"She was sitting importantly behind a big desk.","cn":"她威风地坐在一张大桌子后面。"}}]},"media":{"uk":"media/uk/importantly__gb_1.mp3","us":"media/us/importantly__us_1.mp3"},"examples":[{"en":"She was sitting importantly behind a big desk.","cn":"她神气十足地坐在一张大写字台后面。"},{"en":"More importantly, can he be trusted?","cn":"更重要的是，他值得信任吗？"}]},"imperceptibly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"almost impossible to see or notice","cn":""}]},"examples":[{"en":"Such changes are imperceptible to even the best-trained eye.","cn":"","src":"ld"}],"media":{"uk":"media/uk/imperceptibly__gb_1.mp3","us":"media/us/imperceptibly__us_1.mp3"},"oxford":{"phon":"ˌɪmpəˈseptəbli","pos":"adverb","senses":[{"en":"in a very small way that cannot be seen or felt","cn":"（小得）无法察觉的，感觉不到的","ex":{"en":"The daylight faded almost imperceptibly into night.","cn":"天光渐暗，夜晚悄然降临。"}}]}},"impress":{"oxford":{"phon":"ɪmˈpres","pos":"verb","senses":[{"en":"if a person or thing impresses you, you admire them or it","cn":"使赞叹；使钦佩；使留下深刻的好印象","g":"[transitive, intransitive]","ex":{"en":"We interviewed a number of candidates but none of them impressed us.","cn":"我们面试了数名应聘者，但没有觉得哪一位特别出色。"}},{"en":"to make somebody understand how important, serious, etc. something is by emphasizing it","cn":"使意识到（重要性或严肃性等）","g":"[transitive]","lab":"formal","ex":{"en":"He impressed on us the need for immediate action.","cn":"他让我们认识到立刻采取行动的必要。"}},{"en":"to have a great effect on something, especially somebody’s mind, imagination, etc.","cn":"使铭记；给…留下深刻印象","g":"[transitive]","lab":"formal","ex":{"en":"Her words impressed themselves on my memory.","cn":"她的话语我铭记在心里。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"给…深刻印象;使钦佩","en":"If something impresses you, you feel great admiration for it.","ex":{"en":"What impressed him most was their speed","cn":"最令他佩服的是他们的速度。"}},{"pos":"VERB 动词","cn":"使铭记;使谨记","en":"If you impress something on someone, you make them understand its importance or degree.","ex":{"en":"I had always impressed upon the children that if they worked hard they would succeed in life","cn":"我总让孩子们牢记努力工作就会成功。"}},{"pos":"VERB 动词","cn":"使…注意到;给…留下印象","en":"If something impresses itself on your mind, you notice and remember it.","ex":{"en":"But this change has not yet impressed itself on the minds of the British public.","cn":"但这一变化还没有引起英国公众的注意。"}},{"pos":"VERB 动词","cn":"给…留下(…的)印象","en":"If someone or something impresses you as a particular thing, usually a good one, they gives you the impression of being that thing.","ex":{"en":"Billy Sullivan had impressed me as a fine man.","cn":"比利·沙利文给我留下的印象是他是个很不错的人。"}}]},"media":{"uk":"media/uk/impress__gb_1.mp3","us":"media/us/impress__us_1.mp3"},"examples":[{"en":"We interviewed a number of candidates but none of them impressed us.","cn":"我们和数名申请人进行了面谈，但都没有给我们留下什么印象。"},{"en":"He impressed on us the need for immediate action.","cn":"他让我们认识到立刻采取行动的必要。"}]},"impoverished":{"media":{"uk":"media/uk/impoverished__gb_1.mp3","us":"media/us/impoverished__us_1.mp3"},"oxford":{"phon":"ɪmˈpɒvərɪʃt","pos":"adjective","senses":[{"en":"very poor; without money","cn":"赤贫的；不名一文的","ex":{"en":"impoverished peasants","cn":"贫困的农民"}},{"en":"poor in quality, because something is missing","cn":"贫乏的；贫瘠的；枯竭的"}]},"examples":[{"en":"the impoverished areas of the city","cn":"这个城市的贫民区"},{"en":"impoverished peasants","cn":"贫困的农民"}]},"imposition":{"media":{"uk":"media/uk/imposition__gb_1.mp3","us":"media/us/imposition__us_1.mp3"},"oxford":{"phon":"ˌɪmpəˈzɪʃn","pos":"noun","senses":[{"en":"the act of introducing something such as a new law or rule, or a new tax","cn":"（新法律或规则等的）颁布，实施；（新税的）征收","g":"[uncountable]","ex":{"en":"the imposition of martial law","cn":"戒严令的实施"}},{"en":"an unfair or unreasonable thing that somebody expects or asks you to do","cn":"不公平（或不合理）的要求","g":"[countable]","ex":{"en":"I'd like to stay if it's not too much of an imposition.","cn":"如果不会给您增添太多麻烦，我倒愿意留下。"}}]},"examples":[{"en":"I'd like to stay if it's not too much of an imposition.","cn":"如果不会给您增添太多麻烦，我倒愿意留下。"},{"en":"the imposition of tax on domestic fuel","cn":"家用燃料税的征收"}]},"impromptu":{"media":{"uk":"media/uk/impromptu__gb_1.mp3","us":"media/us/impromptu__us_1.mp3"},"oxford":{"phon":"ɪmˈprɒmptjuː","pos":"adverb","senses":[{"en":"without preparation or planning","cn":"无准备的；即兴的；即席的","ex":{"en":"Roy came up and just started speaking impromptu.","cn":"罗伊走过来，开始即兴讲话。"}},{"en":"done without preparation or planning","cn":"无准备的；即兴的；即席的","ex":{"en":"an impromptu speech","cn":"即兴讲演"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"即兴的;事先无准备的","en":"An impromptu action is one that you do without planning or organizing it in advance.","ex":{"en":"This afternoon the Palestinians held an impromptu press conference","cn":"今天下午巴勒斯坦方面临时召开了记者招待会。"}}]},"examples":[{"en":"an impromptu speech","cn":"即兴讲演"}]},"implicitly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"suggested or understood without being stated directly","cn":""},{"en":"forming a central part of something, but without being openly stated","cn":""}]},"examples":[{"en":"Her words contained an implicit threat.","cn":"","src":"ld"},{"en":"His statement is being seen as implicit criticism of the work of research laboratories.","cn":"","src":"ld"}],"media":{"uk":"media/uk/implicitly__gb_1.mp3","us":"media/us/implicitly__us_1.mp3"},"oxford":{"phon":"ɪmˈplɪsɪtli","pos":"adverb","senses":[{"en":"in a way that is suggested without being directly expressed","cn":"含蓄的；不直接言明的","ex":{"en":"It reinforces, implicitly or explicitly, the idea that money is all-important.","cn":"这或隐或显地强化了金钱至上这一观念。"}},{"en":"completely and without any doubt","cn":"完全的；无疑问的","ex":{"en":"I trust John implicitly.","cn":"我毫无保留地信任约翰。"}}]}},"impractical":{"oxford":{"phon":"ɪmˈpræktɪkl","pos":"adjective","senses":[{"en":"not sensible or realistic","cn":"不明智的；不现实的","ex":{"en":"It was totally impractical to think that we could finish the job in two months.","cn":"认为我们能在两个月之内完成这项工作，这完全是不切实际的。"}},{"en":"not good at doing things that involve using the hands; not good at planning or organizing things","cn":"手不灵巧的；不善于规划（或组织）的","ex":{"en":"He was a wonderful companion but hopelessly impractical.","cn":"他是一个很棒的伴侣，但非常不切实际。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不切实际的;不现实的;不可行的","en":"If you describe an object, idea, or course of action as impractical, you mean that it is not sensible or realistic, and does not work well in practice.","ex":{"en":"When stalking subjects, a tripod is impractical","cn":"潜步跟踪目标时,用三脚架是不切实际的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无动手能力的;无实践能力的","en":"If you describe someone as impractical, you mean that they do not have the abilities or skills to do practical work such as making, repairing, or organizing things.","ex":{"en":"Geniuses are supposed to be eccentric and hopelessly impractical.","cn":"天才通常都被认为行为古怪而且毫无实践能力。"}}]},"media":{"uk":"media/uk/impractical__gb_1.mp3","us":"media/us/impractical__us_1.mp3"},"examples":[{"en":"It was totally impractical to think that we could finish the job in two months.","cn":"认为我们能在两个月之内完成这项工作，这完全是不切实际的。"},{"en":"The road toll scheme was dismissed as impractical.","cn":"公路收费计划由于不切实际而遭到否定。"}]},"imperial":{"media":{"uk":"media/uk/imperial__gb_1.mp3","us":"media/us/imperial__us_1.mp3"},"oxford":{"phon":"ɪmˈpɪəriəl","pos":"adjective","senses":[{"en":"connected with an empire","cn":"帝国的；皇帝的","ex":{"en":"the imperial family/palace/army","cn":"皇室家族；皇宫；皇家陆军"}},{"en":"connected with the system for measuring length, weight and volume using pounds, inches, etc.","cn":"（度量衡）英制的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"帝国的;皇帝的","en":"Imperial is used to refer to things or people that are or were connected with an empire.","ex":{"en":"...the Imperial Palace in Tokyo","cn":"东京的皇宫"}},{"pos":"ADJ 形容词","cn":"(度量衡)英制的","en":"The imperial system of measurement uses inches, feet, and yards to measure length, ounces and pounds to measure weight, and pints and gallons to measure volume."}]},"examples":[{"en":"the imperial family/palace/army","cn":"皇室家族；皇宫；皇家陆军"},{"en":"imperial power/expansion","cn":"皇权；帝国的扩张"}]},"imply":{"media":{"uk":"media/uk/imply__gb_1.mp3","us":"media/us/imply__us_1.mp3"},"oxford":{"phon":"ɪmˈplaɪ","pos":"verb","senses":[{"en":"to suggest that something is true or that you feel or think something, without saying so directly","cn":"含有…的意思；暗示；暗指","ex":{"en":"Are you implying (that) I am wrong?","cn":"你的意思是不是说我错了？"}},{"en":"to make it seem likely that something is true or exists","cn":"说明；表明","ex":{"en":"The survey implies (that) more people are moving house than was thought.","cn":"调查显示，准备搬家的人比想象的要多。"}},{"en":"to make something necessary in order to be successful","cn":"必然包含；使有必要","ex":{"en":"The project implies an enormous investment in training.","cn":"这个项目需要在培训方面做巨大的投资。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"暗指;暗示","en":"If you imply that something is the case, you say something which indicates that it is the case in an indirect way.","ex":{"en":"'Are you implying that I have something to do with those attacks?' she asked coldly","cn":"“你在暗示我和那些袭击有关吗？”她冷冷地问。"}},{"pos":"VERB 动词","cn":"含有…的意思;意味着","en":"If an event or situation implies that something is the case, it makes you think it likely that it is the case.","ex":{"en":"Exports in June rose 1.5%, implying that the economy was stronger than many investors had realized","cn":"6 月份出口上升 1.5%,表明经济比许多投资者所认为的更要坚挺。"}}]},"examples":[{"en":"The survey implies (that) more people are moving house than was thought.","cn":"调查显示，准备搬家的人口比想像的要多。"},{"en":"The project implies an enormous investment in training.","cn":"这个项目需要在培训方面做巨大的投资。"}]},"imagine":{"media":{"uk":"media/uk/imagine__gb_1.mp3","us":"media/us/imagine__us_1.mp3"},"oxford":{"phon":"ɪˈmædʒɪn","pos":"verb","senses":[{"en":"to form a picture in your mind of what something might be like","cn":"想象；设想","g":"[transitive, intransitive]","lab":"informal","ex":{"en":"The house was just as she had imagined it.","cn":"这房子正如她所想象的。"}},{"en":"to believe something that is not true","cn":"误以为；胡乱猜想；猜测","g":"[transitive]","ex":{"en":"He’s always imagining (that) we’re talking about him behind his back.","cn":"他总是胡乱猜想我们在背后说他的闲话。"}},{"en":"to think that something is probably true","cn":"料想；认为","g":"[intransitive, transitive]","lab":"British English or formal, North American English，，","ex":{"en":"‘Can we still buy tickets for the concert?’ ‘I imagine so.’","cn":"“我们还能买到音乐会的票吗？”“我想可以吧。”"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"想象;设想","en":"If you imagine something, you think about it and your mind forms a picture or idea of it.","ex":{"en":"He could not imagine a more peaceful scene","cn":"他想象不出比这更祥和的景象。"}},{"pos":"VERB 动词","cn":"猜测;猜想;认为","en":"If you imagine that something is the case, you think that it is the case.","ex":{"en":"I imagine you're referring to Jean-Paul Sartre","cn":"我猜你说的是让－保罗·萨特。"}},{"pos":"VERB 动词","cn":"臆想;幻想","en":"If you imagine something, you think that you have seen, heard, or experienced that thing, although actually you have not.","ex":{"en":"I realised that I must have imagined the whole thing.","cn":"我意识到大概整件事都是我臆想出来的。"}}]},"examples":[{"en":"Can you imagine what it must be like to lose your job after 20 years?","cn":"你能想像得出干了 20 年之后被辞退会是什么样的滋味吗？"},{"en":"‘Can we still buy tickets for the concert?’ ‘I imagine so. ’ “","cn":"我们还能买到音乐会的票吗？” “我想可以吧。”"}]},"immoral":{"oxford":{"phon":"ɪˈmɒrəl","pos":"adjective","senses":[{"en":"not considered to be good or honest by most people","cn":"不道德的；邪恶的","ex":{"en":"It's immoral to steal.","cn":"偷盗是不道德的。"}},{"en":"not following accepted standards of sexual behaviour","cn":"放荡的；淫荡的","ex":{"en":"an immoral act/life/person","cn":"淫荡的举动／生活／人"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不道德的;道德败坏的","en":"If you describe someone or their behaviour as immoral, you believe that their behaviour is morally wrong.","ex":{"en":"...those who think that birth control and abortion are immoral.","cn":"那些认为节育与堕胎是不道德行为的人"}}]},"media":{"uk":"media/uk/immoral__gb_1.mp3","us":"media/us/immoral__us_1.mp3"},"examples":[{"en":"There's nothing immoral about wanting to earn more money.","cn":"想多赚点钱没什么不道德。"},{"en":"They were charged with living off immoral earnings (= money earned by working as a prostitute ).","cn":"她们被控靠卖淫为生。"}]},"imaginative":{"media":{"uk":"media/uk/imaginative__gb_1.mp3","us":"media/us/imaginative__us_1.mp3"},"oxford":{"phon":"ɪˈmædʒɪnətɪv","pos":"adjective","senses":[{"en":"having or showing new and exciting ideas","cn":"富于想象力的；创新的","ex":{"en":"an imaginative approach/idea/child","cn":"有创意的方法／思想／孩子"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"富于想象力的;有独创性的","en":"If you describe someone or their ideas as imaginative, you are praising them because they are easily able to think of or create new or exciting things.","ex":{"en":"...an imaginative writer.","cn":"想象力丰富的作家"}}]},"examples":[{"en":"The stables have been imaginatively converted into offices.","cn":"马房被别出心裁地改成了办公室。"},{"en":"recipes that make imaginative use of seasonal vegetables","cn":"妙用时令蔬菜的菜谱"}]},"imitate":{"media":{"uk":"media/uk/imitate__gb_1.mp3","us":"media/us/imitate__us_1.mp3"},"oxford":{"phon":"ˈɪmɪteɪt","pos":"verb","senses":[{"en":"to copy somebody/something","cn":"模仿；仿效","ex":{"en":"Her style of painting has been imitated by other artists.","cn":"她的绘画风格为其他画家所模仿。"}},{"en":"to copy the way a person speaks or behaves, in order to make people laugh","cn":"模仿（某人的言谈举止）；作滑稽模仿","ex":{"en":"She knew that the girls used to imitate her and laugh at her behind her back.","cn":"她知道那些女孩子过去常在背地里模仿她、嘲笑她。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"模仿;仿效;模拟","en":"If you imitate someone, you copy what they do or produce.","ex":{"en":"...a genuine German musical which does not try to imitate the American model.","cn":"不刻意模仿美国模式的真正的德国音乐剧"}},{"pos":"VERB 动词","cn":"(为逗乐)戏仿，学…的样子","en":"If you imitate a person or animal, you copy the way they speak or behave, usually because you are trying to be funny.","ex":{"en":"Clarence screws up his face and imitates the Colonel again.","cn":"克拉伦斯又板起面孔,模仿起上校来。"}}]},"examples":[{"en":"She knew that the girls used to imitate her and laugh at her behind her back.","cn":"她知道那些女孩子过去常在背地里模仿她、嘲笑她。"},{"en":"No computer can imitate the complex functions of the human brain.","cn":"任何计算机都无法模拟人脑的复杂功能。"}]},"immutable":{"media":{"uk":"media/uk/immutable__gb_1.mp3","us":"media/us/immutable__us_1.mp3"},"oxford":{"phon":"ɪˈmjuːtəbl","pos":"adjective","senses":[{"en":"that cannot be changed; that will never change","cn":"不可改变的；永恒不变的","ex":{"en":"This decision should not be seen as immutable.","cn":"不该把这个决定看作是不可改变的。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"永远不变的;永恒的","en":"Something that is immutable will never change or cannot be changed.","ex":{"en":"...the eternal and immutable principles of right and wrong.","cn":"永恒不变的对错法则"}}]},"examples":[{"en":"This decision should not be seen as immutable.","cn":"不该把这个决定看成是不可改变的。"}]},"impacted":{"media":{"uk":"media/uk/impacted__gb_1.mp3","us":"media/us/impacted__us_1.mp3"},"oxford":{"phon":"ɪmˈpæktɪd","pos":"adjective","senses":[{"en":"that cannot grow correctly because it is under another tooth","cn":"阻生的","ex":{"en":"an impacted wisdom tooth","cn":"阻生智齿。"}}]}},"important":{"media":{"uk":"media/uk/important__gb_1.mp3","us":"media/us/important__us_1.mp3"},"oxford":{"phon":"ɪmˈpɔːtnt","pos":"adjective","senses":[{"en":"having a great effect on people or things; of great value","cn":"重要的；有重大影响的；有巨大价值的","lab":"British English","ex":{"en":"an important issue/question/point/factor","cn":"重要事项／问题；要点；重要因素"}},{"en":"having great influence or authority","cn":"影响很大的；权威的","ex":{"en":"an important member of the team","cn":"举足轻重的一位队员"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"重要的;必要的;非常有价值的","en":"Something that is important is very significant, is highly valued, or is necessary.","ex":{"en":"Her sons are the most important thing in her life","cn":"她生命中最重要的是她的儿子们。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有声望的;有影响的;显要的","en":"Someone who is important has influence or power within a society or a particular group.","ex":{"en":"He was the most important person on the island.","cn":"他是岛上最有声望的人。"}}]},"examples":[{"en":"Money played an important role in his life.","cn":"金钱在他的生活中扮演了重要的角色。"},{"en":"She was sitting importantly behind a big desk.","cn":"她神气十足地坐在一张大写字台后面。"}]},"imprudent":{"media":{"uk":"media/uk/imprudent__gb_1.mp3","us":"media/us/imprudent__us_1.mp3"},"oxford":{"phon":"ɪmˈpruːdnt","pos":"adjective","senses":[{"en":"not wise or sensible","cn":"不明智的；不谨慎的","ex":{"en":"It would be imprudent to invest all your money in one company.","cn":"把所有的钱都投资在一家公司是不明智的。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不谨慎的;轻率的","en":"If you describe someone's behaviour as imprudent, you think it is not sensible or carefully thought out.","ex":{"en":"...an imprudent investment","cn":"一笔轻率的投资"}}]},"examples":[{"en":"It would be imprudent to invest all your money in one company.","cn":"把所有的钱都投资在一家公司是不明智的。"},{"en":"The banks made hundreds of imprudent loans in the 1970s. 20","cn":"世纪70年代那几家银行轻率地发放了几百笔贷款。"}]},"immaculate":{"media":{"uk":"media/uk/immaculate__gb_1.mp3","us":"media/us/immaculate__us_1.mp3"},"oxford":{"phon":"ɪˈmækjələt","pos":"adjective","senses":[{"en":"perfectly clean and tidy, with no marks or flaws","cn":"十分整洁的；一尘不染的","ex":{"en":"She always looks immaculate.","cn":"她总是打扮得干净利落。"}},{"en":"containing no mistakes or faults","cn":"无误的；无过失的","ex":{"en":"an immaculate performance","cn":"完美的演出"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"干净整洁的;纤尘不染的","en":"If you describe something as immaculate, you mean that it is extremely clean, tidy, or neat.","ex":{"en":"Her front room was kept immaculate.","cn":"她的客厅一尘不染。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无瑕疵的;完美的","en":"If you say that something is immaculate, you are emphasizing that it is perfect, without any mistakes or bad parts at all.","ex":{"en":"The goalkeeper's performance was immaculate.","cn":"守门员的表现堪称完美。"}}]},"examples":[{"en":"She always looks immaculate.","cn":"她总是打扮得干净利落。"},{"en":"an immaculate uniform/room","cn":"整洁的制服/房间"}]},"imitation":{"oxford":{"phon":"ˌɪmɪˈteɪʃn","pos":"noun","senses":[{"en":"a copy of something, especially something expensive","cn":"仿制品；赝品","g":"[countable]","ex":{"en":"a poor/cheap imitation of the real thing","cn":"低劣的仿制品"}},{"en":"the act of copying somebody/something","cn":"模仿；效仿","g":"[uncountable]","ex":{"en":"A child learns to talk by imitation.","cn":"小孩子通过模仿学会说话。"}},{"en":"an act of copying the way somebody talks and behaves, especially to make people laugh","cn":"模仿（某人）的言谈举止；（尤指）滑稽模仿","g":"[countable]","ex":{"en":"He does an imitation of Donald Trump.","cn":"他滑稽地模仿唐纳德·特朗普。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"仿制;仿造;仿造品","en":"An imitation of something is a copy of it.","ex":{"en":"...the most accurate imitation of Chinese architecture in Europe.","cn":"全欧洲最逼真的仿中国样式的建筑"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(对某人动作的)模仿","en":"Imitation means copying someone else's actions.","ex":{"en":"They discussed important issues in imitation of their elders","cn":"他们模仿长辈的口气讨论重要问题。"}},{"pos":"ADJ 形容词","cn":"人造的;仿制的;伪造的","en":"Imitation things are not genuine but are made to look as if they are.","ex":{"en":"...a complete set of Dickens bound in imitation leather.","cn":"一套仿皮本的狄更斯全集"}},{"pos":"N-COUNT 可数名词","cn":"(为逗乐而对某人进行的)模仿,戏仿","en":"If someone does an imitation of another person, they copy the way they speak or behave, sometimes in order to be funny.","ex":{"en":"He gave his imitation of Queen Elizabeth's royal wave","cn":"他模仿伊丽莎白女王挥手致意。"}}]},"media":{"uk":"media/uk/imitation__gb_1.mp3","us":"media/us/imitation__us_1.mp3"},"examples":[{"en":"Many corporate methods have been adopted by American managers in imitation of Japanese practice.","cn":"美国的营商者采用了很多取法日本的公司经营之道。"},{"en":"This latest production is a pale imitation of the original (= it is not nearly as good).","cn":"最新推出的制作远不如它所依据的原着精彩。"}]},"image":{"media":{"uk":"media/uk/image__gb_1.mp3","us":"media/us/image__us_1.mp3"},"oxford":{"phon":"ˈɪmɪdʒ","pos":"noun","senses":[{"en":"a picture, photograph or statue that represents somebody/something","cn":"画像；雕像；塑像","g":"[countable]","ex":{"en":"Most simple leaflets will include text and images.","cn":"大多数简单的传单都会有文字和图像。"}},{"en":"a picture of somebody/something seen in a mirror, through a camera, or on a television, computer, phone, etc.","cn":"镜像；影像；映像；图像","g":"[countable]","ex":{"en":"He stared at his own image reflected in the water.","cn":"他凝视着自己在水中的倒影。"}},{"en":"the impression that a person, an organization, a product, etc. gives to the public","cn":"形象；印象；声誉","g":"[countable, uncountable]","ex":{"en":"His public image is very different from the real person.","cn":"他的公众形象和本人截然不同。"}},{"en":"a mental picture that you have of what somebody/something is like or looks like","cn":"（心目中的）形象，印象","g":"[countable]","ex":{"en":"images of the past","cn":"对过去的印象"}},{"en":"a word or phrase used with a different meaning from its normal one, in order to describe something in a way that produces a strong picture in the mind","cn":"比喻；意象","g":"[countable]","ex":{"en":"Her writings are full of poetic images of the countryside.","cn":"她的作品里充满了富有诗意的乡村意象。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(头脑中的)形象,概念","en":"If you have an image of something or someone, you have a picture or idea of them in your mind.","ex":{"en":"The image of art theft as a gentleman's crime is outdated","cn":"把盗窃艺术品看作是一种绅士犯罪的观念已经过时了。"}},{"pos":"N-COUNT 可数名词","cn":"(个人、团队或组织的)形象,声誉","en":"The image of a person, group, or organization is the way that they appear to other people.","ex":{"en":"The Prime Minister knows that his personal image is his greatest political asset","cn":"总理知道他的个人形象是他最重要的政治资产。"}},{"pos":"N-COUNT 可数名词","cn":"图像；映像；影像","en":"An image is a picture of someone or something.","ex":{"en":"...photographic images of young children","cn":"小孩子们的照片"}},{"pos":"N-COUNT 可数名词","cn":"诗意的描绘;生动的描绘","en":"An image is a poetic description of something.","ex":{"en":"The natural images in the poem are meant to be suggestive of realities beyond themselves.","cn":"诗中描绘的自然景象意在让人联想到景象以外的现实。"}},{"pos":"PHRASE 短语","cn":"是…的翻版;长相酷似…","en":"If you are the image of someone else, you look very much like them.","ex":{"en":"Marianne's son was the image of his father.","cn":"玛丽安娜的儿子长得酷似他父亲。"}},{"pos":"See also:","cn":"","en":"spitting image→see: ;"}]},"examples":[{"en":"His public image is very different from the real person.","cn":"他在公众心目中的形象与他真实的本人截然不同。"},{"en":"Images of deer and hunters decorate the cave walls.","cn":"洞穴壁上装饰着鹿和猎人的画像。"}]},"immersion":{"oxford":{"phon":"ɪˈmɜːʃn","pos":"noun","senses":[{"en":"the act of putting somebody/something into a liquid, especially so that they or it are completely covered; the state of being covered by a liquid","cn":"浸没；浸","ex":{"en":"Immersion in cold water resulted in rapid loss of heat.","cn":"浸泡在冷水中导致热量迅速散失。"}},{"en":"the state of being completely involved in something","cn":"沉浸；专心；陷入","ex":{"en":"his long immersion in politics","cn":"他长期潜心从政"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"潜心钻研;专心","en":"Someone's immersion in a subject is their complete involvement in it.","ex":{"en":"...long-term assignments that allowed them total immersion in their subjects.","cn":"可以让他们潜心研究课题的长期任务"}},{"pos":"N-UNCOUNT 不可数名词","cn":"浸没;浸泡","en":"Immersion of something in a liquid means putting it into the liquid so that it is completely covered.","ex":{"en":"The wood had become swollen from prolonged immersion.","cn":"因长时间浸泡，木头发胀了。"}}]},"media":{"uk":"media/uk/immersion__gb_1.mp3","us":"media/us/immersion__us_1.mp3"},"examples":[{"en":"a two-week immersion course in French (= in which the student will hear and use only French)","cn":"两周的沉浸式法语课程（学生身处完全的法语环境中）"},{"en":"Immersion in cold water resulted in rapid loss of heat.","cn":"浸泡在冷水中导致热量迅速散失。"}]},"impacting":{"oxford":{"phon":"ˈɪmpækt","pos":"noun","senses":[{"en":"the powerful effect that sth has on sb/sth","cn":"巨大影响；强大作用"},{"en":"the act of one object hitting another; the force with which this happens","cn":"撞击；冲撞；冲击力"}]},"media":{"uk":"media/uk/impact__gb_1.mp3","us":"media/us/impact__us_1.mp3"}},"improve":{"media":{"uk":"media/uk/improve__gb_1.mp3","us":"media/us/improve__us_1.mp3"},"oxford":{"phon":"ɪmˈpruːv","pos":"verb","senses":[{"en":"to become better than before; to make something/somebody better than before","cn":"改进；改善","ex":{"en":"Overall the situation has improved dramatically.","cn":"总的来说，情况改善了很多。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"改进;改善;增进","en":"If something improves or if you improve it, it gets better.","ex":{"en":"Both the texture and condition of your hair should improve","cn":"你头发的发质与健康状况都应改善。"}},{"pos":"V-ERG 及物/不及物动词","cn":"提高;(使)变得更熟练","en":"If a skill you have improves or you improve a skill, you get better at it.","ex":{"en":"Their French has improved enormously","cn":"他们的法语进步很大。"}},{"pos":"VERB 动词","cn":"康复;健康好转","en":"If you improve after an illness or an injury, your health gets better or you get stronger.","ex":{"en":"He had improved so much the doctor had cut his dosage.","cn":"他康复很快,医生已减少了用药剂量。"}},{"pos":"VERB 动词","cn":"超过;胜过","en":"If you improve on a previous achievement of your own or of someone else, you achieve a better standard or result.","ex":{"en":"We need to improve on our performance against France.","cn":"我们需要比对阵法国队时表现得更好。"}}]},"examples":[{"en":"The company needs to improve performance in all these areas.","cn":"公司需要在所有这些方面改善业绩。"},{"en":"We've certainly improved on last year's figures.","cn":"我们的业绩的确超过了去年的数字。"}]},"immense":{"media":{"uk":"media/uk/immense__gb_1.mp3","us":"media/us/immense__us_1.mp3"},"oxford":{"phon":"ɪˈmens","pos":"adjective","senses":[{"en":"extremely large or great","cn":"极大的；巨大的","ex":{"en":"There is still an immense amount of work to be done.","cn":"还有非常非常多的工作要做。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"广大的;巨大的","en":"If you describe something as immense, you mean that it is extremely large or great.","ex":{"en":"...an immense cloud of smoke","cn":"大片的烟云"}}]},"examples":[{"en":"There is still an immense amount of work to be done.","cn":"还有非常非常多的工作要做。"},{"en":"The benefits are immense.","cn":"效益是极大的。"}]},"implication":{"media":{"uk":"media/uk/implication__gb_1.mp3","us":"media/us/implication__us_1.mp3"},"oxford":{"phon":"ˌɪmplɪˈkeɪʃn","pos":"noun","senses":[{"en":"a possible effect or result of an action or a decision","cn":"可能的影响（或作用、结果）","g":"[countable, usually plural]","ex":{"en":"They failed to consider the wider implications of their actions.","cn":"他们没有考虑到他们的行动会产生更广泛的影响。"}},{"en":"something that is suggested or indirectly stated (= something that is implied)","cn":"含意；暗指","g":"[countable, uncountable]","ex":{"en":"The implication in his article is that being a housewife is greatly inferior to every other occupation.","cn":"他那篇文章的含意是，当家庭主妇远远不如所有其他职业。"}},{"en":"the fact of being involved, or of involving somebody, in something, especially a crime","cn":"（被）牵连，牵涉","g":"[uncountable]","ex":{"en":"He resigned after his implication in a sex scandal.","cn":"他因卷入一桩性丑闻而辞职。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"可能引发的后果","en":"The implications of something are the things that are likely to happen as a result.","ex":{"en":"The Attorney General was aware of the political implications of his decision to prosecute","cn":"司法部长很清楚他决定起诉可能引发的政治后果。"}},{"pos":"N-COUNT 可数名词","cn":"暗示;暗指;含意","en":"The implication of a statement, event, or situation is what it implies or suggests is the case.","ex":{"en":"The implication was obvious: vote for us or it will be very embarrassing for you","cn":"弦外之音很明显：投票给我们,否则你会非常难堪。"}}]},"examples":[{"en":"The implication in his article is that being a housewife is greatly inferior to every other occupation.","cn":"他那篇文章的含意是，当家庭主妇远远不如所有其他职业。"},{"en":"They failed to consider the wider implications of their actions.","cn":"他们没有考虑到他们的行动会产生更广泛的影响。"}]},"imminent":{"media":{"uk":"media/uk/imminent__gb_1.mp3","us":"media/us/imminent__us_1.mp3"},"oxford":{"phon":"ˈɪmɪnənt","pos":"adjective","senses":[{"en":"likely to happen very soon","cn":"即将发生的；临近的","ex":{"en":"the imminent threat of invasion","cn":"迫在眉睫的入侵威胁"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指不愉快的事)临近的，即将发生的，逼近的","en":"If you say that something is imminent, especially something unpleasant, you mean it is almost certain to happen very soon.","ex":{"en":"There appeared no imminent danger","cn":"眼前似乎没有危险。"}}]},"examples":[{"en":"The system is in imminent danger of collapse.","cn":"这个体制面临着崩溃的危险。"},{"en":"An announcement about his resignation is imminent.","cn":"马上就要宣布他的辞职。"}]},"immigration":{"media":{"uk":"media/uk/immigration__gb_1.mp3","us":"media/us/immigration__us_1.mp3"},"oxford":{"phon":"ˌɪmɪˈɡreɪʃn","pos":"noun","senses":[{"en":"the process of coming to live permanently in a different country from the one you were born in; the number of people who do this","cn":"移居（入境）；移民人数","ex":{"en":"legal/illegal immigration","cn":"合法/非法移民"}},{"en":"the place at a port, an airport, etc. where the passports and other documents of people coming into a country are checked","cn":"移民局检查站","ex":{"en":"We landed at Heathrow and went through customs and immigration.","cn":"我们在希思罗机场降落，之后办理了海关和移民入境检查手续。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"移居","en":"Immigration is the coming of people into a country in order to live and work there.","ex":{"en":"The government has decided to tighten its immigration policy.","cn":"政府决定实施更加严格的移民政策。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"移民局检查处","en":"Immigration or immigration control is the place at a port, airport, or international border where officials check the passports of people who wish to come into the country."}]},"examples":[{"en":"laws restricting immigration into the US","cn":"美国限制外来移民的法律"},{"en":"a rise/fall in immigration","cn":"移民人数的增加/减少"}]},"improvement":{"media":{"uk":"media/uk/improvement__gb_1.mp3","us":"media/us/improvement__us_1.mp3"},"oxford":{"phon":"ɪmˈpruːvmənt","pos":"noun","senses":[{"en":"the act of making something better; the process of something becoming better","cn":"改善；改进","g":"[uncountable]","ex":{"en":"The economy has shown significant improvement over the past 9 months.","cn":"过去 9 个月，经济大有改善。"}},{"en":"a change in something that makes it better; something that is better than it was before","cn":"改进处；改善的事物","g":"[countable]","ex":{"en":"a significant/dramatic improvement","cn":"重大的／巨大的改进"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"改进(之处);改善(之处)","en":"If there is an improvement in something, it becomes better. If you make improvements to something, you make it better.","ex":{"en":"...the dramatic improvements in organ transplantation in recent years","cn":"近几年器官移植方面取得的巨大进步"}},{"pos":"N-COUNT 可数名词","cn":"更优秀之物;改善的事物","en":"If you say that something is an improvement on a previous thing or situation, you mean that it is better than that thing.","ex":{"en":"The new Prime Minister is an improvement on his predecessor","cn":"新上任的总理比他的前任要强。"}}]},"examples":[{"en":"We expect to see further improvement over the coming year.","cn":"我们期望来年会有更进一步的改善。"},{"en":"Sales figures continue to show signs of improvement.","cn":"销售额持续显示出增加的迹象。"}]},"impaired":{"oxford":{"phon":"ɪmˈpeəd","pos":"adjective","senses":[{"en":"not working as it normally would or as it does in most people","cn":"受损的；损坏的；出毛病的","ex":{"en":"impaired vision/memory","cn":"受损的视力／记忆力"}},{"en":"having a particular kind of disability","cn":"有…缺陷的；有…障碍的","lab":"sometimes offensive","ex":{"en":"people who are visually/cognitively impaired","cn":"视障人士；有认知障碍的人"}}]},"media":{"uk":"media/uk/impaired__gb_1.mp3","us":"media/us/impaired__us_1.mp3"},"examples":[{"en":"Nowadays we say someone is ‘speech-impaired’, not dumb.","cn":"现在我们说某个人“有语言障碍”，而不说是哑巴。"},{"en":"impaired vision/memory","cn":"受损的视力/记忆力"}]},"implement":{"oxford":{"phon":"ˈɪmplɪment","pos":"verb","senses":[{"en":"to make something that has been officially decided start to happen or be used","cn":"使生效；贯彻；执行；实施","ex":{"en":"to implement changes/decisions/policies/reforms","cn":"实行变革；执行决议／政策；实施改革"}},{"en":"a tool or an instrument, often one that is quite simple and that is used outdoors","cn":"工具，器具（常指简单的户外用具）","ex":{"en":"agricultural implements","cn":"农具"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"履行;实施","en":"If you implement something such as a plan, you ensure that what has been planned is done.","ex":{"en":"The government promised to implement a new system to control financial loan institutions","cn":"政府许诺实施新的制度来控制金融贷款机构。"}},{"pos":"N-COUNT 可数名词","cn":"工具;器具;用具","en":"An implement is a tool or other piece of equipment.","ex":{"en":"...knives and other useful implements.","cn":"刀子和其他有用工具"}}]},"media":{"uk":"media/uk/implement__gb_1.mp3","us":"media/us/implement__us_1.mp3"},"examples":[{"en":"the implementation of the new system","cn":"新体制的实施"},{"en":"to implement changes/decisions/policies/reforms","cn":"实行变革；执行决议/政策；实施改革"}]},"impression":{"media":{"uk":"media/uk/impression__gb_1.mp3","us":"media/us/impression__us_1.mp3"},"oxford":{"phon":"ɪmˈpreʃn","pos":"noun","senses":[{"en":"an idea, a feeling or an opinion that you get about somebody/something, or that somebody/something gives you","cn":"印象；感想","sc":"idea/opinion","ex":{"en":"My first impression of him was favourable.","cn":"他给我的第一印象不错。"}},{"en":"the effect that an experience or a person has on somebody/something","cn":"影响；效果","sc":"effect","ex":{"en":"You'll have to play better than that if you really want to make an impression (= to make people admire you).","cn":"你如果真的想给人留下好印象，就得表现得更好一点。"}},{"en":"a drawing showing what a person looks like or what a place or a building will look like in the future","cn":"印象画","sc":"drawing","ex":{"en":"This is an artist's impression of the new stadium.","cn":"这是一位艺术家对未来新运动场作的印象画。"}},{"en":"a clever or funny copy of the way a person acts or speaks","cn":"（对某人举止言谈的）滑稽模仿","sc":"copy of somebody","ex":{"en":"He did an impression of Tom Hanks.","cn":"他滑稽地模仿了汤姆·汉克斯。"}},{"en":"an appearance that may be false","cn":"（虚假的）外观；假象","sc":"false appearance","ex":{"en":"Clever lighting creates an impression of space in a room.","cn":"巧妙的照明会让人有屋子空间增大的感觉。"}},{"en":"a mark that is left when an object is pressed hard into a surface","cn":"压痕","sc":"mark","ex":{"en":"The dentist made an impression of his teeth.","cn":"牙医给他的牙齿留下了印模。"}},{"en":"all the copies of a book that are printed at one time, with few or no changes to the contents since the last time the book was printed","cn":"重印本；印次","sc":"book"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"印象;感想","en":"Your impression of a person or thing is what you think they are like, usually after having seen or heard them. Your impression of a situation is what you think is going on.","ex":{"en":"What were your first impressions of college?","cn":"你对大学的第一印象是什么？"}},{"pos":"N-SING 单数名词","cn":"(通常有悖事实的)感觉,假象","en":"If someone gives you a particular impression, they cause you to believe that something is the case, often when it is not.","ex":{"en":"I don't want to give the impression that I'm running away from the charges","cn":"我不想给人一种我在逃避指控的感觉。"}},{"pos":"N-COUNT 可数名词","cn":"(通常指对名人的)滑稽模仿","en":"An impression is an amusing imitation of someone's behaviour or way of talking, usually someone well-known.","ex":{"en":"He did impressions of Sean Connery and James Mason.","cn":"他对肖恩·康纳利和詹姆斯·梅森进行了滑稽模仿。"}},{"pos":"N-COUNT 可数名词","cn":"压痕;印痕;印记","en":"An impression of an object is a mark or outline that it has left after being pressed hard onto a surface.","ex":{"en":"...the world's oldest fossil impressions of plant life.","cn":"世界上最古老的植物化石印痕"}},{"pos":"PHRASE 短语","cn":"产生影响;起作用","en":"If someone or something makes an impression, they have a strong effect on people or a situation.","ex":{"en":"He has told me his plans and he's made a good impression on me","cn":"他告诉了我他的计划,给我留下了一个好印象。"}},{"pos":"PHRASE 短语","cn":"(误)认为;(错)以为","en":"If you are under the impression that something is the case, you believe that it is the case, usually when it is not actually the case.","ex":{"en":"He had apparently been under the impression that a military coup was in progress.","cn":"他显然以为一场军事政变正在酝酿中。"}}]},"examples":[{"en":"You'll have to play better than that if you really want to make an impression (= to make people admire you).","cn":"你如果真的想给人留下好印象，就得表现得更好。"},{"en":"This is an artist's impression of the new stadium.","cn":"这是一位艺术家对未来新运动场作的印象画。"}]},"imperfect":{"media":{"uk":"media/uk/imperfect__gb_1.mp3","us":"media/us/imperfect__us_1.mp3"},"oxford":{"phon":"ɪmˈpɜːfɪkt","pos":"adjective","senses":[{"en":"containing faults or mistakes; not complete or perfect","cn":"有缺点的；有缺陷的；不完全的；不完美的","ex":{"en":"an imperfect world","cn":"不完美的世界"}},{"en":"the form of a verb that expresses action in the past that is not complete. It is often called the past progressive or past continuous.","cn":"过去未完成时（常称为过去进行时）","ex":{"en":"In ‘while I was washing my hair’, the verb is in the imperfect.","cn":"while I was washing my hair 中的动词是过去未完成时。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不完美的;有缺点的;有瑕疵的","en":"Something that is imperfect has faults and is not exactly as you would like it to be.","ex":{"en":"We live in an imperfect world","cn":"我们生活在一个并不完美的世界上。"}},{"pos":"N-SING 单数名词","cn":"(动词的)未完成过去式，未完成过去时","en":"In grammar, the imperfect or the imperfect tense of a verb is used to describe continuous situations or repeated actions in the past. Examples are 'I was reading' and 'they were eating'."}]},"examples":[{"en":"All our sale items are slightly imperfect.","cn":"我们所有的廉价商品都稍有缺陷。"},{"en":"In ‘while I was washing my hair’, the verb is in the imperfect. * while I was washing my hair","cn":"中的动词是过去未完成时。"}]},"immigrants":{"oxford":{"phon":"ˈɪmɪɡrənt","pos":"noun","senses":[{"en":"a person who has come to live permanently in a country that is not their own （","cn":"外来）移民；外侨"}]}},"implied":{"oxford":{"phon":"ɪmˈplaɪd","pos":"adjective","senses":[{"en":"suggested without being directly expressed","cn":"含蓄的；不直接言明的","ex":{"en":"I disliked the implied criticism in his voice.","cn":"我讨厌他暗含批评的口吻。"}}]}},"images":{"oxford":{"phon":"ˈɪmɪdʒ","pos":"noun","senses":[{"en":"the impression that a person, an organization or a product, etc. gives to the public","cn":"形象；印象；声誉"},{"en":"a mental picture that you have of what sb/sth is like or looks like （","cn":"心目中的）形象，印象"}]}},"implications":{"oxford":{"phon":"ˌɪmplɪˈkeɪʃn","pos":"noun","senses":[{"en":"a possible effect or result of an action or a decision","cn":"可能的影响（或作用、结果）"},{"en":"something that is suggested or indirectly stated (= sth that is implied)","cn":"含意；暗指"}]}},"imprisoned":{"oxford":{"phon":"ɪmˈprɪzn","pos":"verb","senses":[{"en":"to put sb in a prison or another place from which they cannot escape","cn":"监禁；关押"}]}},"impacts":{"oxford":{"phon":"ˈɪmpækt","pos":"noun","senses":[{"en":"the powerful effect that sth has on sb/sth","cn":"巨大影响；强大作用"},{"en":"the act of one object hitting another; the force with which this happens","cn":"撞击；冲撞；冲击力"}]}},"improving":{"oxford":{"phon":"ɪmˈpruːv","pos":"verb","senses":[{"en":"to become better than before; to make sth/sb better than before","cn":"改进；改善"},{"en":"to achieve or produce sth that is of a better quality than sth else","cn":"改进；做出比 … 更好的成绩"}]}},"implies":{"oxford":{"phon":"ɪmˈplaɪ","pos":"verb","senses":[{"en":"to suggest that sth is true or that you feel or think sth, without saying so directly","cn":"含有 … 的意思；暗示；暗指"},{"en":"to make it seem likely that sth is true or exists","cn":"说明；表明"}]}},"improved":{"oxford":{"phon":"ɪmˈpruːv","pos":"verb","senses":[{"en":"to become better than before; to make sth/sb better than before","cn":"改进；改善"},{"en":"to achieve or produce sth that is of a better quality than sth else","cn":"改进；做出比 … 更好的成绩"}]},"media":{"uk":"media/ldoce/hwd/bre/c/improved0205.mp3","us":"media/ldoce/hwd/ame/9/laadimproved.mp3"},"examples":[{"en":"Our washing powder now has a new improved formula.","cn":"我们的洗衣粉现已有改良的新配方。"},{"en":"improved performance","cn":"更好的性能"}]},"imprinted":{"oxford":{"phon":"ɪmˈprɪnt","pos":"verb","senses":[{"en":"to have a great effect on sth so that it cannot be forgotten, changed, etc.","cn":"产生重大影响；铭刻；使铭记"},{"en":"to print or press a mark or design onto a surface","cn":"印；压印"}]}},"imported":{"oxford":{"phon":"ˈɪmpɔːt","pos":"noun","senses":[{"en":"a product or service that is brought into one country from another","cn":"进口；输入的产品（或劳务）"},{"en":"the act of bringing a product or service into one country from another （","cn":"产品、劳务的）进口，输入，引进"}]},"media":{"uk":"media/ldoce/hwd/bre/c/import_v0205.mp3","us":"media/ldoce/hwd/ame/1/l3import2.mp3"},"examples":[{"en":"In 2001, Britain exported more cars than it imported.","cn":""},{"en":"All the meat is imported from France.","cn":""}]},"improves":{"oxford":{"phon":"ɪmˈpruːv","pos":"verb","senses":[{"en":"to become better than before; to make sth/sb better than before","cn":"改进；改善"},{"en":"to achieve or produce sth that is of a better quality than sth else","cn":"改进；做出比 … 更好的成绩"}]}},"imagined":{"oxford":{"phon":"ɪˈmædʒɪn","pos":"verb","senses":[{"en":"to form a picture in your mind of what sth might be like","cn":"想像；设想"},{"en":"to believe sth that is not true","cn":"误以为；胡乱猜想；猜测"}]}},"imposed":{"oxford":{"phon":"ɪmˈpəʊz","pos":"verb","senses":[{"en":"to introduce a new law, rule, tax, etc; to order that a rule, punishment, etc. be used","cn":"推行，采用（规章制度）；强制实行"},{"en":"to force sb/sth to have to deal with sth that is difficult or unpleasant","cn":"迫使；把 … 强加于"}]}},"improvements":{"oxford":{"phon":"ɪmˈpruːvmənt","pos":"noun","senses":[{"en":"the act of making sth better; the process of sth becoming better","cn":"改善；改进"},{"en":"a change in sth that makes it better; sth that is better than it was before","cn":"改进处；改善的事物"}]}},"imperfection":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"缺点;弱点;缺陷","en":"An imperfection in someone or something is a fault, weakness, or undesirable feature that they have.","ex":{"en":"By his own statement, there have been imperfections in his judgment.","cn":"据他自己声称,他的判断存在不足之处。"}},{"pos":"N-COUNT 可数名词","cn":"污点;瑕疵","en":"An imperfection in something is a small mark or damaged area which may spoil its appearance.","ex":{"en":"...imperfections in the cloth.","cn":"衣料上的瑕疵"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not completely correct or perfect","cn":""},{"en":"something such as a plan, idea, or system that is flawed , has a fault which prevents it from working as well as it should do","cn":""},{"en":"not completely correct or perfect","cn":""}]},"collocations":{"phrases":["ADJ. moral, physical","VERB + IMPERFECTION cover up | reveal, show up","PREP. ~ in Careful inspection in daylight revealed imperfections in the paintwork."]},"media":{"uk":"media/ldoce/hwd/bre/3/imperfect_adj0205.mp3","us":"media/ldoce/hwd/ame/8/imperfect1.mp3"},"examples":[{"en":"They learned to live with each other's imperfections.","cn":"他们学会了容忍对方的缺点。"},{"en":"the imperfect world we live in","cn":""}],"oxford":{"phon":"ˌɪmpəˈfekʃn","pos":"noun","senses":[{"en":"a fault or weakness in somebody/something","cn":"缺点；瑕疵","ex":{"en":"They learned to live with each other's imperfections.","cn":"他们学会了容忍对方的缺点。"}}]}},"immigrant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(外来)移民;侨民","en":"An immigrant is a person who has come to live in a country from some other country.","ex":{"en":"...illegal immigrants.","cn":"非法移民"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who enters another country in order to live there permanently","cn":""},{"en":"someone who enters another country because they are not safe in their own country, for example because there is a war there","cn":""},{"en":"someone who asks to be allowed to enter another country because they are not safe in their own country, especially because of their political beliefs or activities","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"The United States is a country of immigrants — people who come to one country from another country, in hopes of having a better life. If you didn't immigrate to the United States yourself, it is extremely likely that you have at least one recent ancestor who did."}]},"collocations":{"phrases":["ADJ. illegal | foreign | Irish, Italian, Jewish, etc. | recent | would-be | first-generation, second-generation First-generation immigrants ","QUANT. flood, influx, wave","VERB + IMMIGRANT accept, welcome | deport, return ships laden with would-be immigrants who were forcibly returned","IMMIGRANT + VERB arrive, enter sth immigrants seeking to enter the country | come from sth | settle (sth) European immigrants settled much o","IMMIGRANT + NOUN community, family, group, population | worker | labour","PREP. ~ from, ~ to She was the daughter of Chinese immigrants to America."]},"media":{"uk":"media/ldoce/hwd/bre/4/immigrant0205.mp3","us":"media/ldoce/hwd/ame/d/immigrant.mp3"},"examples":[{"en":"immigrant communities/families/workers","cn":"侨民社区/家庭/劳工"},{"en":"illegal immigrants","cn":"非法移民"}],"oxford":{"phon":"ˈɪmɪɡrənt","pos":"noun","senses":[{"en":"a person who has come to live permanently in a different country from the one they were born in","cn":"（外来的）移民","ex":{"en":"immigrants from other European countries","cn":"来自其他欧洲国家的移民"}}]}},"immobile":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"固定的;静止的","en":"Someone or something that is immobile is completely still.","ex":{"en":"Joe remained as immobile as if he had been carved out of rock.","cn":"乔一动不动,仿佛一尊石头雕像。"}},{"pos":"ADJ 形容词","cn":"瘫痪的;不能移动的","en":"Someone or something that is immobile is unable to move or unable to be moved.","ex":{"en":"A riding accident left him immobile.","cn":"一场骑马意外事故导致他瘫痪。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not moving - use this especially about people who are not moving, or about places where there is no wind","cn":""},{"en":"a car, vehicle etc that is not moving","cn":""},{"en":"if traffic is at a standstill it is not moving. If rail or bus services are at a standstill they have stopped operating","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something immobile can't move or be moved — it's locked or stuck in place."}]},"collocations":{"phrases":["VERBS lie, remain, sit, stand She seemed scarcely to breathe as she lay immobile. | become | hold sb, leave sb For a moment shock held her i","ADV. completely, perfectly, totally, utterly | almost, virtually | relatively"]},"media":{"uk":"media/ldoce/hwd/bre/c/immobile0205.mp3","us":"media/ldoce/hwd/ame/f/immobile.mp3"},"examples":[{"en":"His illness has left him completely immobile.","cn":"他的病使他完全丧失了活动能力。"},{"en":"She stood immobile by the window.","cn":"她一动不动地靠窗站着。"}],"oxford":{"phon":"ɪˈməʊbaɪl","pos":"adjective","senses":[{"en":"not moving","cn":"不动的；静止的","ex":{"en":"She stood immobile by the window.","cn":"她一动不动地靠窗站着。"}},{"en":"unable to move","cn":"不能移动的；不能活动的","ex":{"en":"His illness has left him completely immobile.","cn":"他的病使他完全丧失了活动能力。"}}]}},"impetus":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"推动;促进;推动力","en":"Something that gives a process impetus or an impetus makes it happen or progress more quickly.","ex":{"en":"This decision will give renewed impetus to the economic regeneration of east London","cn":"这一决定会给东伦敦的经济复苏带来新的推动力。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"one of several causes of a situation or condition","cn":""},{"en":"the thing or one of the things that makes you decide to do something or makes something happen","cn":""},{"en":"the first causes from which a situation, condition etc has developed","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An impetus is the force behind something, whether it's a boulder rolling down a hill or a person making a decision."}]},"collocations":{"phrases":["ADJ. considerable, great, powerful, strong | main, major | immediate, initial, original | fresh, new, renewed Each new rumour added fresh im","VERB + IMPETUS add, give sb/sth, provide (sb/sth with) The slope added impetus to his speed. | gain, gather, receive The movement is steadil","IMPETUS + VERB come from sth Much of the impetus for change came from customers' opinions.","PREP. ~ behind sb/sth The main impetus behind the move west was to find gold and other minerals. | ~ for the impetus for arms control agreem"]},"media":{"uk":"media/ldoce/hwd/bre/a/impetus0205.mp3","us":"media/ldoce/hwd/ame/e/impetus.mp3"},"examples":[{"en":"The debate seems to have lost much of its initial impetus.","cn":"辩论会似乎没有开始时那么大的冲劲了。"},{"en":"His articles provided the main impetus for change.","cn":"他的那些文章是促进变革的主要推动力。"}],"oxford":{"phon":"ˈɪmpɪtəs","pos":"noun","senses":[{"en":"something that encourages a process or activity to develop more quickly","cn":"动力；推动；促进；刺激","g":"[uncountable, singular]","ex":{"en":"The debate seems to have lost much of its initial impetus.","cn":"辩论会似乎没有开始时那么大的冲劲了。"}},{"en":"the force or energy with which something moves","cn":"动量；动力；惯性","g":"[uncountable]","lab":"specialist","ex":{"en":"The slope added impetus to his speed.","cn":"斜坡令他跑得更快。"}}]}},"immature":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"发育未全的;不成熟的","en":"Something or someone that is immature is not yet completely grown or fully developed.","ex":{"en":"The birds were in immature plumage","cn":"这些鸟儿羽翅未全。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"冒失的;鲁莽的;冲动的","en":"If you describe someone as immature, you are being critical of them because they do not behave in a sensible or responsible way.","ex":{"en":"...grossly immature drivers who flout the rules of the road","cn":"无视交通法规、极端鲁莽的司机"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is childish annoys you by being unreasonable and unhelpful, or by complaining and being rude, as if they were a small child","cn":""},{"en":"someone who is immature behaves as if they were younger than they really are, so they are not as sensible or responsible as you expect them to be","cn":""},{"en":"someone who is juvenile , especially a young adult, behaves in a very silly way like a child, when they should be more sensible","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Use the adjective immature to describe something that is not fully grown: “Elizabeth rescued an immature sparrow that had fallen from its nest during the storm.”"}]},"collocations":{"phrases":["VERBS be, seem","ADV. very | rather, relatively | emotionally, physically, politically, sexually"]},"media":{"uk":"media/ldoce/hwd/bre/d/immature0205.mp3","us":"media/ldoce/hwd/ame/b/immature.mp3"},"examples":[{"en":"immature behaviour","cn":"不成熟的行为"},{"en":"immature plants","cn":"未成长的植物"}],"oxford":{"phon":"ˌɪməˈtjʊə(r)","pos":"adjective","senses":[{"en":"behaving in a way that is not sensible and is typical of people who are much younger","cn":"（行为）不成熟的，不够老练的，幼稚的","ex":{"en":"immature behaviour","cn":"不成熟的行为"}},{"en":"not fully developed or grown","cn":"未长成的；发育未全的","ex":{"en":"immature plants","cn":"未长成的植物"}}]}},"immunize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(常指通过注射疫苗)使免疫","en":"If people or animals are immunized, they are made immune to a particular disease, often by being given an injection.","ex":{"en":"We should require that every student is immunized against hepatitis B","cn":"我们应要求每个学生都注射乙肝疫苗。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to protect someone from a particular illness by giving them a vaccine 〔","cn":"接种疫苗〕使〔人〕免疫"}]},"collocations":{"phrases":["ADV. routinely","PREP. against Children have been routinely immunized against polio since 1958. | with They immunized some mice with a dose of the live vacci"]},"media":{"uk":"media/ldoce/hwd/bre/1/immunize0205.mp3","us":"media/ldoce/hwd/ame/7/immunize.mp3"},"examples":[{"en":"an immunization programme to prevent epidemics","cn":"防止流行病的免疫注射方案"},{"en":"There is still no vaccine to immunize people against the virus.","cn":"现在还没有针对这种病毒的疫苗。"}],"oxford":{"phon":"ˈɪmjunaɪz","pos":"verb","senses":[{"en":"to protect a person or an animal from a disease, especially by giving them an injection of a vaccine","cn":"（尤指通过注射疫苗）使免疫","ex":{"en":"a campaign to immunize children against the common killer diseases","cn":"一项针对常见致命疾病的儿童免疫运动"}}]}},"immediacy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"即时性;紧迫性","en":"The immediacy of an event or situation is the quality that it has which makes it seem important or exciting because it is happening at the present time.","ex":{"en":"Do they understand the immediacy of the crisis?","cn":"他们明白危机的紧迫性吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when something is important or urgent because it relates to a situation or event that is happening now","cn":"即时﹔紧迫﹔刻不容缓"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"Use the noun immediacy to talk about the lighting-fast speed with which something happens. If you order pizza and see the delivery driver pull up in front of your house two minutes later, you'll be amazed at the immediacy of your pizza's arrival."}]},"collocations":{"phrases":["VERB + IMMEDIACY lack","PHRASES a lack of immediacy, a loss of immediacy Television allows viewers to experience an event without any loss of immediacy."]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41immediacy.mp3","us":"media/ldoce/hwd/ame/8/immediacy.mp3"},"examples":[{"en":"Our aim is immediacy of response to emergency calls.","cn":"我们的目标是对紧急求救电话立刻作出回应。"},{"en":"Email lacks the immediacy of online chat.","cn":"电子邮件缺乏在线交谈的即时性。"}],"oxford":{"phon":"ɪˈmiːdiəsi","pos":"noun","senses":[{"en":"the quality in something that makes it seem as if it is happening now, close to you, and is therefore important and requires attention quickly","cn":"直接性；即时性；迫切性","ex":{"en":"the immediacy of threat","cn":"威胁的迫切性"}},{"en":"lack of delay; speed","cn":"立即；迅速","ex":{"en":"Our aim is immediacy of response to emergency calls.","cn":"我们的目标是对紧急求救电话立刻作出回应。"}}]}},"impose":{"collins":{"senses":[{"pos":"VERB 动词","cn":"强制实行;强加","en":"If you impose something on people, you use your authority to force them to accept it.","ex":{"en":"Britain imposed fines on airlines which bring in passengers without proper papers","cn":"英国会对运载证件不齐全的乘客进入国内的航空公司课以罚款。"}},{"pos":"VERB 动词","cn":"把(看法、信仰)强加(于…)","en":"If you impose your opinions or beliefs on other people, you try and make people accept them as a rule or as a model to copy.","ex":{"en":"Parents of either sex should beware of imposing their own tastes on their children.","cn":"父母双方都应切记不要把自己的喜好强加给孩子。"}},{"pos":"VERB 动词","cn":"使遭受，使承受(压力、痛苦等)","en":"If something imposes strain, pressure, or suffering on someone, it causes them to experience it.","ex":{"en":"The filming imposed an additional strain on her.","cn":"拍摄任务使她承受了格外大的压力。"}},{"pos":"VERB 动词","cn":"把…硬加给;把…强塞给;勉强(某人)做事","en":"If someone imposes on you, they unreasonably expect you to do something for them which you do not want to do.","ex":{"en":"I was afraid you'd simply feel we were imposing on you","cn":"我担心你会觉得我们是在勉强你。"}},{"pos":"VERB 动词","cn":"使打扰;使硬缠","en":"If someone imposes themselves on you, they force you to accept their company although you may not want to.","ex":{"en":"I didn't want to impose myself on my married friends.","cn":"我不想打扰自己已婚的朋友。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if you impose your ideas and beliefs on other people, you try to force them to have the same ideas and beliefs as you","cn":""},{"en":"to force someone to accept something that causes them harm or suffering","cn":""},{"en":"to get rid of a thing or piece of work that you do not want by giving it to someone else","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To impose means to force or inflict something on someone else. If you want to impose your musical taste on your parents, play your tunes all day at top volume."}]},"collocations":{"phrases":["ADV. effectively The terms of the contract were effectively imposed rather than agreed. | simply New technology cannot be used successfully ","VERB + IMPOSE seek to, strive to, try to","PREP. on/upon The government has imposed a ban on the sale of handguns."]},"media":{"uk":"media/ldoce/hwd/bre/0/impose0205.mp3","us":"media/ldoce/hwd/ame/b/impose.mp3"},"examples":[{"en":"‘You must stay for lunch.’ ‘Well, thanks, but I don't want to impose … ’ “","cn":"你一定得留下吃午饭。” “唔，谢谢，但我不想添麻烦 … ”"},{"en":"It was noticeable how a few people managed to impose their will on the others.","cn":"显而易见，有少数几个人设法把自己的意志强加于别人。"}],"oxford":{"phon":"ɪmˈpəʊz","pos":"verb","senses":[{"en":"to introduce a new law, rule, tax, etc.; to order that a rule, punishment, etc. be used","cn":"推行，实施（规章制度）；强制实行","g":"[transitive]","ex":{"en":"The UN Security Council imposed sanctions in 1992.","cn":"1992 年，联合国安理会实施了制裁。"}},{"en":"to force somebody/something to have to deal with something that is difficult or unpleasant","cn":"迫使承受；把…强加于","g":"[transitive]","ex":{"en":"He described the limitations imposed by his disease.","cn":"他描述了疾病给他造成的活动限制。"}},{"en":"to make somebody accept the same opinions, wishes, etc. as your own","cn":"使（别人）接受自己的意见","g":"[transitive]","ex":{"en":"She didn't want to impose her values on her family.","cn":"她并不想勉强家人接受自己的价值观。"}},{"en":"to expect somebody to do something for you or to spend time with you, when it may not be convenient for them","cn":"勉强（某人做某事）；硬要…和…在一起","g":"[intransitive]","ex":{"en":"‘You must stay for lunch.’ ‘Well, thanks, but I don’t want to impose…’","cn":"“你一定得留下吃午饭。”“唔，谢谢，但我不想添麻烦…”"}},{"en":"to make somebody/something accept or be aware of your presence or ideas","cn":"使接受，使意识到（自己的在场或想法）","g":"[transitive]","ex":{"en":"European civilization was the first to impose itself across the whole world.","cn":"欧洲文明是最先传播到全世界的。"}}]}},"immerse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使沉浸(于);使专心(于);使深陷(于)","en":"If you immerse yourself in something that you are doing, you become completely involved in it.","ex":{"en":"Since then I've lived alone and immersed myself in my career.","cn":"自那以后,我一直一个人生活,全身心投入我的事业当中。"}},{"pos":"VERB 动词","cn":"使浸没(于液体中)","en":"If something is immersed in a liquid, someone puts it into the liquid so that it is completely covered.","ex":{"en":"The electrodes are immersed in liquid.","cn":"电极浸没在液体中。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to put something into a liquid for a very short time and take it out again","cn":""},{"en":"to put something quickly, firmly, and deeply into a liquid","cn":""},{"en":"to put something such as a piece of bread or cake into a hot drink or soup before eating it","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you immerse yourself in your work, you completely involve yourself in it, spending long hours in the office and thinking about work all the time."}]},"collocations":{"phrases":["ADV. completely, fully, totally | partially","PREP. in The seeds need to be completely immersed in water. 2 concentrate completely on sth","ADV. deeply Clare and Phil were deeply immersed in conversation. | completely, totally | in For six months I totally immersed myself in my w"]},"media":{"uk":"media/ldoce/hwd/bre/2/immerse0205.mp3","us":"media/ldoce/hwd/ame/3/immerse.mp3"},"examples":[{"en":"Clare and Phil were immersed in conversation in the corner.","cn":"克莱尔和菲尔在角落里深谈。"},{"en":"She immersed herself in her work.","cn":"她埋头工作。"}],"oxford":{"phon":"ɪˈmɜːs","pos":"verb","senses":[{"en":"to put somebody/something into a liquid, especially so that they or it are completely covered","cn":"使浸没于","ex":{"en":"The seeds will swell when immersed in water.","cn":"这些种子浸泡在水里就会膨胀。"}},{"en":"to become or make somebody completely involved in something","cn":"（使）深陷于，沉浸在","ex":{"en":"She immersed herself in her work.","cn":"她埋头工作。"}}]}},"impassable":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不能通行的;无法通过的","en":"If a road, path, or route is impassable, it is impossible to travel over because it is blocked or in bad condition."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a road, path, or area that is impassable is impossible to travel along or through","cn":"不能通行的﹐无法通过的"}]},"vocab":{"pos":"adj","senses":[{"en":"Whether it’s a road, a barrier, a river, or an abyss, if you can’t travel through or over it, you can describe it as impassable ."}]},"collocations":{"phrases":["VERBS be | become | remain | make sth | think sth The river's broad mudflats were thought completely impassable.","ADV. completely, totally The mud made the roads impassable. | almost, virtually"]},"media":{"uk":"media/ldoce/hwd/bre/5/impassable0205.mp3","us":"media/ldoce/hwd/ame/6/impassable.mp3"},"examples":[{"en":"The mountains are impassable.","cn":"连绵的群山无法翻越。"}],"oxford":{"phon":"ɪmˈpɑːsəbl","pos":"adjective","senses":[{"en":"impossible to travel on or through, especially because it is in bad condition or it has been blocked by something","cn":"不能通行的（尤指因路况恶劣或被阻断）","ex":{"en":"The mountain roads are totally impassable to cars in winter.","cn":"冬天的山路根本无法通行汽车。"}}]}},"impasse":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"绝境;僵局;死胡同","en":"If people are in a difficult position in which it is impossible to make any progress, you can refer to the situation as an impasse .","ex":{"en":"The company says it has reached an impasse in negotiations with the union.","cn":"公司称与工会的谈判已陷入僵局。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a situation in which no further progress can be made because two groups or organizations cannot find a way to end a disagreement","cn":""},{"en":"a situation in which progress has stopped completely, especially because people cannot agree on what to do next","cn":""},{"en":"to slowly stop making any progress","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When two huge semi trailers met face-to-face on a one-lane mountain road, the drivers jumped out of their cabs and exclaimed, \"We're at an impasse ! We can't move forward — we can only reverse and go back in the direction from which we came.\""}]},"collocations":{"phrases":["ADJ. diplomatic, legal, political","VERB + IMPASSE reach Negotiations seemed to have reached an impasse. | break, end, overcome, resolve","PHRASES a way out of an impasse The proposal offered both sides a way out of the diplomatic impasse."]},"media":{"uk":"media/ldoce/hwd/bre/f/impasse_las3_br.mp3","us":"media/ldoce/hwd/ame/b/impasse.mp3"},"examples":[{"en":"Negotiations have reached an impasse.","cn":"谈判已陷入僵局。"},{"en":"to break/end the impasse","cn":"打破/结束僵局"}],"oxford":{"phon":"ˈɪmpæs","pos":"noun","senses":[{"en":"a difficult situation in which no progress can be made because the people involved cannot agree what to do","cn":"僵局；绝境","ex":{"en":"to break/end the impasse","cn":"打破／结束僵局"}}]}},"impracticable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能实行的;行不通的","en":"If something such as a course of action is impracticable, it is impossible to do.","ex":{"en":"Such measures would be highly impracticable and almost impossible to apply.","cn":"这样的措施非常不切实际,几乎不可能付诸实施。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"impossible or very difficult to do for practical reasons","cn":"不切实际的﹔不可行的"}]},"collocations":{"phrases":["VERBS be, prove, seem | become | make sth, render sth The damage it would cause makes the idea utterly impracticable. | consider sth, find s","ADV. highly | completely, quite, totally, utterly"]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41impracticable.mp3","us":"media/ldoce/hwd/ame/8/impracticable.mp3"},"examples":[{"en":"It would be impracticable for each member to be consulted on every occasion.","cn":"不可能每一次都征求每个成员的意见。"},{"en":"It was an appealing plan but quite impracticable.","cn":"这个计划有吸引力﹐但基本行不通。"}],"oxford":{"phon":"ɪmˈpræktɪkəbl","pos":"adjective","senses":[{"en":"impossible or very difficult to do; not practical in a particular situation","cn":"不可行的；不切实际的","ex":{"en":"It would be impracticable for each member to be consulted on every occasion.","cn":"不可能每一次都征求每个成员的意见。"}}]}},"impartial":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不偏不倚的;公正的;无偏见的","en":"Someone who is impartial is not directly involved in a particular situation, and is therefore able to give a fair opinion or decision about it.","ex":{"en":"As an impartial observer my analysis is supposed to be objective","cn":"作为中立的观察员,我的分析应该客观。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not influenced by personal opinions or emotions, especially when you have to make a decision about something","cn":""},{"en":"able to make fair judgements or decisions about a situation because you do not support anyone who is involved in it","cn":""},{"en":"not supporting any side in a disagreement, argument, war etc","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're in a contest you'd better hope the judges are impartial , that is, that they aren't biased toward one competitor over another."}]},"collocations":{"phrases":["VERBS be | remain The judge must remain impartial.","ADV. completely, quite, strictly, totally | fairly, reasonably, relatively"]},"media":{"uk":"media/ldoce/hwd/bre/f/impartial0205.mp3","us":"media/ldoce/hwd/ame/6/impartial.mp3"},"examples":[{"en":"As chairman, I must remain impartial.","cn":"作为主席，我必须保持中立。"},{"en":"an impartial inquiry/observer","cn":"公正的调查/观察者"}],"oxford":{"phon":"ɪmˈpɑːʃl","pos":"adjective","senses":[{"en":"not supporting one person or group more than another","cn":"公正的；不偏不倚的；中立的","ex":{"en":"an impartial inquiry/observer","cn":"公正的调查／观察者"}}]}},"impede":{"collins":{"senses":[{"pos":"VERB 动词","cn":"妨碍;阻碍;阻止","en":"If you impede someone or something, you make their movement, development, or progress difficult.","ex":{"en":"Fallen rock is impeding the progress of rescue workers.","cn":"坠落的石头阻滞了救援人员的救援进程。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make it very difficult for an activity or plan to continue successfully","cn":""},{"en":"to cause problems and therefore delay the development or progress of something","cn":""},{"en":"to make progress or the development of something slower or more difficult","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To impede something is to delay or block its progress or movement. Carrying six heavy bags will impede your progress if you're trying to walk across town."}]},"collocations":{"phrases":["ADV. greatly, seriously, significantly The bad weather seriously impeded our progress."]},"media":{"uk":"media/ldoce/hwd/bre/2/impede0205.mp3","us":"media/ldoce/hwd/ame/2/impede.mp3"},"examples":[{"en":"Work on the building was impeded by severe weather.","cn":"楼房的施工因天气恶劣而停了下来。"},{"en":"Storms at sea impeded our progress .","cn":"海上风暴阻碍了我们的航程。"}],"oxford":{"phon":"ɪmˈpiːd","pos":"verb","senses":[{"en":"to delay or stop the progress of something","cn":"阻碍；阻止","ex":{"en":"Work on the building was impeded by severe weather.","cn":"楼房的施工因天气恶劣而停了下来。"}}]}},"improbable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不大可能的;未必会(发生)的","en":"Something that is improbable is unlikely to be true or to happen.","ex":{"en":"...a highly improbable coincidence","cn":"几率非常小的巧合"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇异的;荒谬的","en":"If you describe something as improbable, you mean it is strange, unusual, or ridiculous.","ex":{"en":"On the face of it, their marriage seems an improbable alliance.","cn":"表面上看,他们的婚姻似乎是个荒谬的结合。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"difficult or impossible to believe","cn":""},{"en":"a story, explanation, or excuse that is unlikely cannot be believed because it is so unusual","cn":""},{"en":"a statement or event that is improbable is difficult to believe, even though it may in fact be true or may actually have happened","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Your parents might tell you it's improbable that they'll buy you a car when you turn 16. Since improbable means something is unlikely but not impossible, your optimism allows you to keep hoping."}]},"collocations":{"phrases":["VERBS appear, be, look, seem, sound | become | make sth These new facts make the theory improbable.","ADV. extremely, highly, very, wildly a wildly improbable idea | completely, quite | not altogether | fairly, rather, slightly | inherently, "]},"media":{"uk":"media/ldoce/hwd/bre/6/improbable0205.mp3","us":"media/ldoce/hwd/ame/4/improbable.mp3"},"examples":[{"en":"He claimed, improbably, that he had never been there.","cn":"他声称从未去过那里，令人觉得不可靠。"},{"en":"It seems improbable that the current situation will continue.","cn":"当前的局势似乎不大可能继续下去。"}],"oxford":{"phon":"ɪmˈprɒbəbl","pos":"adjective","senses":[{"en":"not likely to be true or to happen","cn":"不大可能真实的（或发生的）；不大可能的","ex":{"en":"an improbable story","cn":"大概不是真实的故事"}},{"en":"seeming strange because it is not what you would expect","cn":"奇异的；荒谬的","ex":{"en":"Her hair was an improbable shade of yellow.","cn":"她的头发带有怪怪的黄色。"}}]}},"imperative":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极重要的;必要的;紧急的","en":"If it is imperative that something is done, that thing is extremely important and must be done.","ex":{"en":"It was imperative that he act as naturally as possible","cn":"最重要的是他要做到尽可能自然。"}},{"pos":"N-COUNT 可数名词","cn":"必要的事;紧急的事;必须履行的责任","en":"An imperative is something that is extremely important and must be done.","ex":{"en":"The most important political imperative is to limit the number of US casualties.","cn":"现在的头等政治大事就是要控制美国人的伤亡人数。"}},{"pos":"N-SING 单数名词","cn":"祈使语气","en":"In grammar, a clause that is in the imperative, or in the imperative mood, contains the base form of a verb and usually has no subject. Examples are 'Go away' and 'Please be careful'. Clauses of this kind are typically used to tell someone to do something."},{"pos":"N-COUNT 可数名词","cn":"祈使语气动词","en":"An imperative is a verb in the base form that is used, usually without a subject, in an imperative clause."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely important and needing to be done or dealt with immediately","cn":"紧急的﹐极重要的"},{"en":"an imperative verb is one that expresses an order, such as ‘stand up’ 〔","cn":"动词〕祈使的"},{"en":"something that must be done urgently","cn":"紧急的事"}]},"vocab":{"pos":"1 adj n 2 adj n","senses":[{"en":"When something absolutely has to be done and cannot be put off, use the adjective imperative ."}]},"collocations":{"phrases":["VERBS be, seem | become | remain It remains imperative that all sides should be involved in the talks. | make sth The collapse of the wall m","ADV. absolutely"]},"media":{"uk":"media/ldoce/hwd/bre/0/imperative_adj0205.mp3","us":"media/ldoce/hwd/ame/f/imperative1.mp3"},"examples":[{"en":"the economic imperative of quality education for all","cn":"向全民提供高质量教育对经济发展的重要性"},{"en":"It is absolutely imperative that we finish by next week.","cn":"我们的当务之急是必须于下周完成。"}],"oxford":{"phon":"ɪmˈperətɪv","pos":"adjective","senses":[{"en":"very important and needing immediate attention or action","cn":"重要紧急的；迫切的；急需处理的","g":"[not usually before noun]","lab":"formal","ex":{"en":"It is absolutely imperative that we finish by next week.","cn":"我们必须于下周完工。"}},{"en":"expressing authority","cn":"表示权威的","lab":"formal","ex":{"en":"an imperative tone","cn":"命令的语调"}},{"en":"expressing an order","cn":"表示命令的；祈使的","g":"[only before noun]","lab":"grammar","ex":{"en":"an imperative sentence","cn":"祈使句"}},{"en":"a thing that is very important and needs immediate attention or action; a factor that makes something necessary","cn":"重要紧急的事；必要的事","lab":"formal","ex":{"en":"the economic imperative of quality education for all","cn":"向全民提供优质教育对经济发展的重要性"},"pos":"noun"},{"en":"the form of a verb that expresses an order; a verb in this form","cn":"祈使语气；祈使语气动词","lab":"grammar","ex":{"en":"‘Go away!’ is an imperative.","cn":"Go away! 是祈使句。"},"pos":"noun"}]}},"impotence":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"无能力;不起作用","en":"Impotence is a lack of power to influence people or events.","ex":{"en":"...a sense of impotence in the face of deplorable events.","cn":"面对悲惨事件无能为力的感觉"}},{"pos":"N-UNCOUNT 不可数名词","cn":"阳痿;性无能","en":"Impotence is a man's sexual problem in which his penis fails to get hard or stay hard.","ex":{"en":"Impotence affects 10 million men in the US alone.","cn":"仅仅在美国,就有 1,000 万男子患有阳痿。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to take effective action because you do not have enough power, strength, or control","cn":""},{"en":"a man who is impotent is unable to have sex because he cannot get an erection","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Impotence is the state of being weak or unable to accomplish something, like the impotence a broom in clearing a foot of snow from your sidewalk."}]},"collocations":{"phrases":["ADJ. total | relative | male | political, sexual","PHRASES a feeling/sense of impotence Violence may result from a sense of impotence."]},"media":{"uk":"media/ldoce/hwd/bre/5/impotent0205.mp3","us":"media/ldoce/hwd/ame/7/impotent.mp3"},"examples":[{"en":"a feeling of impotence in the face of an apparently insoluble problem","cn":"面对显然无法解决的问题的无力感"},{"en":"male impotence","cn":"阳痿"}],"oxford":{"phon":"ˈɪmpətəns","pos":"noun","senses":[{"en":"the fact of being unable to change things or influence a situation","cn":"无能为力的；不起作用的","ex":{"en":"a feeling of impotence in the face of an apparently insoluble problem","cn":"面对显然无法解决的问题时的无力感"}},{"en":"a condition in which a man is unable to achieve an erection and is therefore unable to have full sex","cn":"性无能的；阳痿的","ex":{"en":"male impotence","cn":"阳痿"}}]}},"imprecise":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不清楚的;不精确的;不准确的","en":"Something that is imprecise is not clear, accurate, or precise.","ex":{"en":"The charges were vague and imprecise","cn":"指控的内容模糊不清。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having more than one possible meaning and therefore confusing and unclear","cn":""},{"en":"words or statements that are imprecise are unclear because they do not describe or explain something in an exact way when this is necessary","cn":""},{"en":"unclear, especially because not enough details are given","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you’re being imprecise, you’re not being exact. If you try to draw a perfect circle with your eyes closed, your drawing will probably be imprecise ."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. extremely, very | fairly, rather, somewhat | notoriously &lsquo;Breach of the peace&rsquo; is a notoriously imprecise notion.","PREP. about She was rather imprecise about the cost of the trip."]},"media":{"uk":"media/ldoce/hwd/bre/f/imprecise0205.mp3","us":"media/ldoce/hwd/ame/1/laadimprecise.mp3"},"examples":[{"en":"These terms are often used imprecisely and interchangeably.","cn":"这些词语的使用常常不够精确，而且常常交互使用。"},{"en":"The witness's descriptions were too imprecise to be of any real value.","cn":"证人的描述太不明确，没有任何实际价值。"}],"oxford":{"phon":"ˌɪmprɪˈsaɪs","pos":"adjective","senses":[{"en":"not giving exact details or making something clear","cn":"不确切的；不精确的；不明确的","ex":{"en":"an imprecise definition","cn":"不确切的定义"}}]}},"impertinent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不礼貌的;傲慢的;莽撞的","en":"If someone talks or behaves in a rather impolite and disrespectful way, you can say that they are being impertinent .","ex":{"en":"Would it be impertinent to ask where exactly you were?","cn":"能冒昧问一下您所在的确切位置吗？"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not following the rules of good social behaviour or treating other people with a lack of respect","cn":""},{"en":"not following the rules of good social behaviour. Impolite sounds rather formal","cn":""},{"en":"behaving in a way that is a little rude, especially when this is amusing or annoying – used especially about children","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"If someone's rude without being openly nasty, like a kid in the back row of class quietly heckling his teacher, you can call him impertinent ."}]},"collocations":{"phrases":["VERBS be, seem | get Don't you get impertinent with me! | find sth She found the question highly impertinent.","ADV. highly, very | slightly, somewhat"]},"media":{"uk":"media/ldoce/hwd/bre/8/impertinent0205.mp3","us":"media/ldoce/hwd/ame/2/impertinent.mp3"},"examples":[{"en":"Would it be impertinent to ask why you're leaving?","cn":"问一下你为什么要离开不知是否唐突？"},{"en":"She had the impertinence to ask my age!","cn":"她居然探问我的年龄，真没礼貌！"}],"oxford":{"phon":"ɪmˈpɜːtɪnənt","pos":"adjective","senses":[{"en":"rude and not showing respect for somebody who is older or more important","cn":"粗鲁无礼的；不敬的","lab":"British English","ex":{"en":"an impertinent question/child","cn":"没有礼貌的提问／孩子"}}]}},"imbalance":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不平衡;不均衡;失衡","en":"If there is an imbalance in a situation, the things involved are not the same size, or are not the right size in proportion to each other.","ex":{"en":"...the imbalance between the two sides in this war.","cn":"这场战争中双方力量的悬殊"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a disproportionate share of something is higher than it should be because the thing has not been shared equally","cn":""},{"en":"a state in which two things are not equal, especially if this is unfair or causes problems","cn":""},{"en":"a lack of a fair or correct balance between two things, which results in problems or unfairness","cn":"不平衡﹔失调"}]},"vocab":{"pos":"n","senses":[{"en":"An imbalance occurs when you have too much of some things and too little of others. If you put so much pepper in your soup that you can't taste the other spices, then you caused an imbalance in your flavoring."}]},"collocations":{"phrases":["ADJ. growing | regional | gender, power, trade | chemical, hormonal","VERB + IMBALANCE cause, create | correct, redress Increased recruitment of women engineers will help correct the gender imbalance in the pro","IMBALANCE + VERB arise, occur","PREP. ~ between an imbalance between imports and exports | ~ in An imbalance in certain chemicals leads to disturbances in the brain's funct"]},"media":{"uk":"media/ldoce/hwd/bre/2/imbalance0205.mp3","us":"media/ldoce/hwd/ame/e/imbalance.mp3"},"examples":[{"en":"Attempts are being made to redress (= put right) the imbalance between our import and export figures.","cn":"我们正努力纠正进出口的不平衡。"},{"en":"a global imbalance of/in power","cn":"全球权力的不平衡"}],"oxford":{"phon":"ɪmˈbæləns","pos":"noun","senses":[{"en":"a situation in which two or more things are not the same size or are not treated the same, in a way that is unfair or causes problems","cn":"失衡；不平衡；不公平","ex":{"en":"a global imbalance of/in power","cn":"全球权力的不平衡"}}]}},"immaterial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不重要的;无关紧要的","en":"If you say that something is immaterial, you mean that it is not important or not relevant.","ex":{"en":"Whether we like him or not is immaterial.","cn":"我们是否喜欢他无关紧要。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not important in a particular situation","cn":"无关紧要的﹔不相关的"},{"en":"not having a physical body or form","cn":"非实体的﹐无形的"}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"Things that are immaterial have no physical form (like a ghost) or are unimportant (like most ghost stories)."}]},"collocations":{"phrases":["VERBS be, prove, seem | become","ADV. completely, entirely, quite, wholly The condition of the car is quite immaterial as long as it works. | almost, virtually | relatively","PREP. to These facts are immaterial to the problem."]},"media":{"uk":"media/ldoce/hwd/bre/0/immaterial0205.mp3","us":"media/ldoce/hwd/ame/2/immaterial.mp3"},"examples":[{"en":"It is immaterial to me whether he stays or goes.","cn":"他的去留与我无关。"},{"en":"The cost is immaterial.","cn":"费用并不重要。"}],"oxford":{"phon":"ˌɪməˈtɪəriəl","pos":"adjective","senses":[{"en":"not important in a particular situation","cn":"不重要；无关紧要","g":"[not usually before noun]","ex":{"en":"The cost is immaterial.","cn":"费用并不重要。"}},{"en":"not having a physical form","cn":"无形体的；非物质的","lab":"formal","ex":{"en":"an immaterial God","cn":"无形的上帝"}}]}},"impersonal":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"没有人情味的;冷淡的","en":"If you describe a place, organization, or activity as impersonal, you mean that it is not very friendly and makes you feel unimportant because it involves or is used by a large number of people.","ex":{"en":"Before then many children were cared for in large impersonal orphanages","cn":"在那之前,许多孩子被安置在一个缺乏人情味的大孤儿院里。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"客观的;不受个人感情(或偏见)影响的","en":"If you describe someone's behaviour as impersonal, you mean that they do not show any emotion about the person they are dealing with.","ex":{"en":"We must be as impersonal as a surgeon with his knife","cn":"我们必须像外科医生拿手术刀时一样冷静客观,不受任何感情影响。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非个人的;不带个人色彩的","en":"An impersonal room or statistic does not give any information about the character of the person to whom it belongs or relates.","ex":{"en":"The rest of the room was neat and impersonal","cn":"房间的其余部分整洁干净,不带任何的个人色彩。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you feel as though you are not wanted","cn":""},{"en":"unfriendly – used especially about the physical characteristics or appearance of something","cn":""},{"en":"lacking the normal friendly relations between people who work or do business together","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're impersonal, you're neutral — you're not showing your feelings or your preference. If you choose people to be on your team by closing your eyes and pointing, that's impersonal — you're not picking your friends or the best players."}]},"collocations":{"phrases":["VERBS be, seem | become | find sth I find the atmosphere there rather impersonal.","ADV. very | totally | a bit, rather | coldly, coolly His voice was coolly impersonal. | oddly 2 not referring to any particular person","VERBS be | keep sth I think we should keep things entirely impersonal.","ADV. absolutely, completely, entirely, totally"]},"media":{"uk":"media/ldoce/hwd/bre/3/impersonal0205.mp3","us":"media/ldoce/hwd/ame/2/impersonal.mp3"},"examples":[{"en":"We have to do more to stop people trading wild animals illegally.","cn":"我们必须进一步阻止人们非法买卖野生动物。"},{"en":"We clearly need to do more to protect biodiversity.","cn":"很明显，我们需要进一步保护生物多样性。"}],"oxford":{"phon":"ɪmˈpɜːsənl","pos":"adjective","senses":[{"en":"having no friendly human feelings or atmosphere; making you feel unimportant","cn":"缺乏人情味的；冷淡的","lab":"usually disapproving","ex":{"en":"a vast impersonal organization","cn":"庞大而不讲人情的组织"}},{"en":"not referring to any particular person; not concerned with people as individuals","cn":"非指个人的；客观的","ex":{"en":"Let's keep the criticism general and impersonal.","cn":"我们批评时应有普遍性，不要针对个人。"}},{"en":"an impersonal verb or sentence has ‘it’ or ‘there’ as the subject","cn":"（动词或句子）无人称的，非人称的","lab":"grammar"}]}},"implausible":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"难以置信的;不像真实的","en":"If you describe something as implausible, you believe that it is unlikely to be true.","ex":{"en":"I had to admit it sounded like an implausible excuse","cn":"我得承认那听起来像是个难以叫人相信的借口。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"difficult or impossible to believe","cn":""},{"en":"a story, explanation, or excuse that is unlikely cannot be believed because it is so unusual","cn":""},{"en":"a statement or event that is improbable is difficult to believe, even though it may in fact be true or may actually have happened","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Something that's Implausible is farfetched or unlikely. If it's 3pm and you still have to study for three exams and write an essay before midnight, it’s implausible that you’ll also have time to watch a movie."}]},"collocations":{"phrases":["VERBS be, seem, sound | consider sth, deem sth These results migh t be considered implausible .","ADV. highly | quite, totally, wholly This idea is totally implausible. | increasingly He gave a series of increasingly implausible excuses. "]},"media":{"uk":"media/ldoce/hwd/bre/c/implausible0205.mp3","us":"media/ldoce/hwd/ame/4/implausible.mp3"},"examples":[{"en":"It was all highly implausible.","cn":"这毫无道理。"},{"en":"an implausible claim/idea/theory","cn":"悖于情理的要求/思想/理论"}],"oxford":{"phon":"ɪmˈplɔːzəbl","pos":"adjective","senses":[{"en":"not seeming reasonable or likely to be true","cn":"似乎不合情理的；不像真实的","ex":{"en":"an implausible claim/idea/theory","cn":"悖于情理的要求／思想／理论"}}]}},"impinge":{"collins":{"senses":[{"pos":"VERB 动词","cn":"影响;冲击","en":"Something that impinges on you affects you to some extent.","ex":{"en":"...the cuts in defence spending that have impinged on two of the region's largest employers.","cn":"已经冲击到该地区两个最大就业制造者的防御开支削减"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have a harmful effect on someone or something","cn":"对…不利﹔妨碍"}]},"vocab":{"pos":"v","senses":[{"en":"Whether you have a habit of standing too close when talking to others or bringing luggage on a crowded rush-hour subway car, you'll find people don't like it when you impinge on their personal space."}]},"collocations":{"phrases":["ADV. seriously actions which seriously impinge on other people's personal freedoms | hardly | directly, indirectly","PREP. on/upon measures which directly or indirectly impinge upon women's lives"]},"media":{"uk":"media/ldoce/hwd/bre/c/impinge0205.mp3","us":"media/ldoce/hwd/ame/d/impinge.mp3"},"examples":[{"en":"He never allowed his work to impinge on his private life.","cn":"他从不让他的工作妨碍私生活。"},{"en":"Personal problems experienced by students may impinge on their work.","cn":"学生遇到的个人问题可能会影响到他们的学业。"}],"oxford":{"phon":"ɪmˈpɪndʒ","pos":"verb","senses":[{"en":"to have a clear and definite effect on something/somebody, especially a bad one","cn":"对…有明显作用（或影响）；妨碍；侵犯","ex":{"en":"He never allowed his work to impinge on his private life.","cn":"他从不让他的工作妨碍私生活。"}}]}},"imperceptible":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"察觉不出的;感觉不到的;难以察觉的","en":"Something that is imperceptible is so small that it is not noticed or cannot be seen.","ex":{"en":"Brian's hesitation was almost imperceptible.","cn":"布赖恩的犹豫几乎难以察觉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"almost impossible to see or notice","cn":"难以察觉的"}]},"vocab":{"pos":"adj","senses":[{"en":"If it's imperceptible , it's impossible to perceive with any of the senses. The world might be spinning, but it's imperceptible from your couch."}]},"collocations":{"phrases":["VERBS be","ADV. almost, virtually His head moved in an almost imperceptible nod.","PREP. to The slight change in the taste was imperceptible to most people."]},"media":{"uk":"media/ldoce/hwd/bre/9/imperceptible0205.mp3","us":"media/ldoce/hwd/ame/a/imperceptible.mp3"},"examples":[{"en":"imperceptible changes in temperature","cn":"难以觉察的气温变化"},{"en":"Such changes are imperceptible to even the best-trained eye.","cn":"这样的变化即使是对最训练有素的人来说也不易察觉。"}],"oxford":{"phon":"ˌɪmpəˈseptəbl","pos":"adjective","senses":[{"en":"very small and therefore unable to be seen or felt","cn":"（小得）无法察觉的，感觉不到的","ex":{"en":"imperceptible changes in temperature","cn":"难以觉察的气温变化"}}]}},"impropriety":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不合适举止;不正当行为","en":"Impropriety is improper behaviour.","ex":{"en":"He resigned amid allegations of financial impropriety.","cn":"他在财务作假的质疑声中辞职了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"behaviour or an action that is wrong or unacceptable according to moral, social, or professional standards","cn":"不正当的行为[行动]﹔不得体的举止"}]},"vocab":{"pos":"n","senses":[{"en":"When the boss' wife shows up at a formal dinner party and proceeds to stuff her purse full of hors d'oeuvres, no one dares to mention her impropriety above a whisper, especially to the boss."}]},"collocations":{"phrases":["ADJ. gross | constitutional, financial, procedural (law) , sexual","VERB + IMPROPRIETY commit Several employees were suspended amid allegations that financial improprieties had been committed. | accuse sb of ","PHRASES a suggestion of impropriety There is no suggestion of impropriety by the minister."]},"media":{"uk":"media/ldoce/hwd/bre/9/impropriety0205.mp3","us":"media/ldoce/hwd/ame/8/impropriety.mp3"},"examples":[{"en":"Accusations of impropriety were made against the company’s directors.","cn":"对公司董事不正当的行为提出了指控。"}],"oxford":{"phon":"ˌɪmprəˈpraɪəti","pos":"noun","senses":[{"en":"behaviour or actions that are dishonest, morally wrong or not appropriate for a person in a position of responsibility","cn":"（身居要职者）不诚实（或不正当、不合适）的行为举止","ex":{"en":"There was no evidence of impropriety.","cn":"没有行为不当的证据。"}}]}},"immortal":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不朽的；流芳百世的","en":"Someone or something that is immortal is famous and likely to be remembered for a long time.","ex":{"en":"...the immortal Reverend Dr Spooner.","cn":"不朽的斯普纳牧师"}},{"pos":"ADJ 形容词","cn":"不死的;长生的","en":"Someone or something that is immortal will live or last for ever and never die or be destroyed.","ex":{"en":"The pharaohs were considered gods and therefore immortal.","cn":"法老们被视为神灵，且长生不死。"}},{"pos":"ADJ 形容词","cn":"(语句)著名的，不朽的","en":"If you refer to someone's immortal words, you mean that what they said is well-known, and you are usually about to quote it.","ex":{"en":"...Roosevelt's immortal words, 'Speak softly and carry a big stick.'","cn":"罗斯福的不朽名言——“说话温和,手持大棒”"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"music, literature, art etc, that is timeless still seems important and interesting even though it was written or made a long time ago","cn":""},{"en":"immortal words, lines etc are famous and are remembered for a long time after they are written or spoken","cn":""},{"en":"a classic book, film, design etc is one that is important or special and remains popular for a long time","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Immortal describes what will never die. Do you like vampires? Those blood-suckers are immortal, and will live forever — except, of course, if you drive a stake through their heart."}]},"collocations":{"phrases":["VERBS be, seem | become","ADV. almost, virtually | effectively The wild cocoa tree is effectively immortal. | potentially"]},"media":{"uk":"media/ldoce/hwd/bre/2/immortal0205.mp3","us":"media/ldoce/hwd/ame/0/immortal.mp3"},"examples":[{"en":"In the immortal words of Henry Ford, ‘If it ain't broke, don't fix it.’","cn":"按照亨利 · 福特的不朽名言：“如果东西没坏掉，就不要去修理它。”"},{"en":"She is one of the Hollywood immortals.","cn":"她是一位千古流芳的好莱坞名人。"}],"oxford":{"phon":"ɪˈmɔːtl","pos":"adjective","senses":[{"en":"that lives or lasts forever","cn":"长生的；永世的；不朽的","ex":{"en":"The soul is immortal.","cn":"灵魂不灭。"}},{"en":"famous and likely to be remembered forever","cn":"流芳百世的；名垂千古的","ex":{"en":"the immortal Goethe","cn":"名垂千古的歌德"}},{"en":"a person who is so famous that they will be remembered forever","cn":"不朽的人物；名垂千古的人物","ex":{"en":"She is one of the Hollywood immortals.","cn":"她是一位千古流芳的好莱坞名人。"},"pos":"noun"},{"en":"a god or other being who is believed to live forever","cn":"神；永生不灭者","pos":"noun"}]}},"impertinence":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"不礼貌;傲慢;莽撞","en":"If someone talks or behaves in a rather impolite and disrespectful way, you can call this behaviour impertinence or an impertinence .","ex":{"en":"He was punished for his impertinence.","cn":"他因为冒失无礼受到惩罚。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not following the rules of good social behaviour or treating other people with a lack of respect","cn":""},{"en":"not following the rules of good social behaviour. Impolite sounds rather formal","cn":""},{"en":"behaving in a way that is a little rude, especially when this is amusing or annoying – used especially about children","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"You have to be sure your teacher has a good sense of humor before you criticize the way he dresses, otherwise you might be scolded for your impertinence . Impertinence means \"being rude, insolent, or inappropriately playful.\""}]},"collocations":{"phrases":["ADJ. gross I consider his remark a gross impertinence.","VERB + IMPERTINENCE have She had the impertinence to suggest I needed a holiday.","PHRASES the height of impertinence"]},"media":{"uk":"media/ldoce/hwd/bre/8/impertinent0205.mp3","us":"media/ldoce/hwd/ame/2/impertinent.mp3"},"examples":[{"en":"She had the impertinence to ask my age!","cn":"她居然探问我的年龄，真没礼貌！"},{"en":"He was always asking impertinent questions.","cn":""}],"oxford":{"phon":"ɪmˈpɜːtɪnəns","pos":"noun","senses":[{"en":"rude behaviour or comments that show no respect for somebody who is older or more important","cn":"粗鲁无礼的；不敬的","ex":{"en":"She had the impertinence to ask my age!","cn":"她竟然问我的年龄，简直太无礼了！"}}]}},"imperialism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"帝国主义","en":"Imperialism is a system in which a rich and powerful country controls other countries, or a desire for control over other countries."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a political system in which one country rules a lot of other countries","cn":"帝国主义"},{"en":"the way in which a rich or powerful country’s way of life, culture, businesses etc influence and change a poorer country’s way of life etc","cn":"扩张主义﹔势力的扩张"}]},"vocab":{"pos":"n","senses":[{"en":"Imperialism is a type of government that seeks to increase its size, either by forcing (through war) or influencing (through politics) other countries to submit to their rule."}]},"collocations":{"phrases":["ADJ. American, British, Roman, Western, etc. | capitalist, cultural, economic"]},"media":{"uk":"media/ldoce/hwd/bre/7/ld41imperialism.mp3","us":"media/ldoce/hwd/ame/b/imperialism.mp3"},"examples":[{"en":"cultural/economic imperialism","cn":"文化/经济扩张"},{"en":"Roman imperialism","cn":"罗马帝国统治"}],"oxford":{"phon":"ɪmˈpɪəriəlɪzəm","pos":"noun","senses":[{"en":"a system in which one country controls other countries, often after defeating them in a war","cn":"帝国统治；帝国主义","ex":{"en":"Roman imperialism","cn":"罗马帝国统治"}},{"en":"the fact of a powerful country increasing its influence over other countries through business, culture, etc.","cn":"（商业、文化等向外国的）扩张；扩张主义","ex":{"en":"cultural/economic imperialism","cn":"文化／经济扩张"}}]}},"impassive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"喜怒不形于色的;不露感情的;面无表情的","en":"If someone is impassive or their face is impassive, they are not showing any emotion.","ex":{"en":"He searched Hill's impassive face for some indication that he understood","cn":"他盯着希尔毫无表情的面孔，寻找着表明他已明白的些许迹象。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"showing no emotion, interest, or understanding in your expression, for example because you are bored, or have not been paying attention to what is being said","cn":""},{"en":"deliberately showing no humour in your expression, even though what you are saying or doing is meant as a joke","cn":""},{"en":"someone who has an inscrutable expression shows no emotion or reaction, so it is impossible to guess what they are thinking or feeling","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who doesn't seem to react — who is always \"taking a pass\" in the conversation of life can be described as impassive ."}]},"collocations":{"phrases":["VERBS be, sit, stand | become | remain","ADV. completely, quite, totally | almost Her expression was cool, almost impassive. | rather | usually A smile transformed her usually impas"]},"media":{"uk":"media/ldoce/hwd/bre/1/impassive0205.mp3","us":"media/ldoce/hwd/ame/a/impassive.mp3"},"examples":[{"en":"her impassive expression/face","cn":"她冷漠的表情/面容"},{"en":"Her impassive face showed no reaction at all.","cn":"她表情冷淡﹐毫无反应。"}],"oxford":{"phon":"ɪmˈpæsɪv","pos":"adjective","senses":[{"en":"not showing any feeling or emotion","cn":"无表情的；无动于衷的；不动声色的","ex":{"en":"her impassive expression/face","cn":"她冷漠的表情／面容"}}]}},"imprison":{"collins":{"senses":[{"pos":"VERB 动词","cn":"关押;监禁","en":"If someone is imprisoned, they are locked up or kept somewhere, usually in prison as a punishment for a crime or for political opposition.","ex":{"en":"The local priest was imprisoned for 18 months on charges of anti-state agitation","cn":"当地牧师由于受到煽动反对政府的指控而被监禁 18 个月。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"unable to escape from a dangerous place or an unpleasant situation","cn":""},{"en":"to be unable to escape from an unpleasant or boring situation","cn":""},{"en":"to be unable to leave a place, so that you feel bored or very impatient","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To imprison is to hold someone in a prison or jail. It can also mean to confine them elsewhere. You might imprison a classmate in a locker, for example."}]},"collocations":{"phrases":["ADV. virtually Her fear virtually imprisoned her in her home. | falsely, unlawfully, wrongfully, wrongly working on behalf of people who hav","PREP. for He was imprisoned for debt. | in He was imprisoned in a local castle."]},"media":{"uk":"media/ldoce/hwd/bre/3/imprison0205.mp3","us":"media/ldoce/hwd/ame/6/imprison.mp3"},"examples":[{"en":"( figurative ) Some young mothers feel imprisoned in their own homes.","cn":"有些年轻的母亲感到待在家里如同坐牢。"},{"en":"They were imprisoned for possession of drugs.","cn":"他们因藏毒品而被监禁。"}],"oxford":{"phon":"ɪmˈprɪzn","pos":"verb","senses":[{"en":"to put somebody in a prison or another place from which they cannot escape","cn":"监禁；关押","lab":"figurative","ex":{"en":"They were imprisoned for possession of drugs.","cn":"他们因持有毒品而被监禁。"}}]}},"impediment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"妨碍;阻碍;障碍物","en":"Something that is an impediment to a person or thing makes their movement, development, or progress difficult.","ex":{"en":"He was satisfied there was no legal impediment to the marriage.","cn":"这一婚姻没有任何司法上的障碍，他对此很满意。"}},{"pos":"N-COUNT 可数名词","cn":"(言语)障碍","en":"Someone who has a speech impediment has a disability which makes speaking difficult.","ex":{"en":"John's slight speech impediment made it difficult for his mother to understand him.","cn":"约翰有轻微的言语障碍，这令母亲很难理解他的话。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a physical problem that makes speaking, hearing, or moving difficult 〔","cn":"生理问题导致的〕言语[听觉﹐行动]障碍"},{"en":"a situation or event that makes it difficult or impossible for someone or something to succeed or make progress","cn":"阻碍﹐障碍(物)﹔绊脚石"}]},"vocab":{"pos":"n","senses":[{"en":"An impediment is anything that slows or blocks progress. It can refer to a physical thing, like a fallen tree in the road, or something more intangible, like how piracy is an impediment to the pleasure cruise industry in Somalia."}]},"collocations":{"phrases":["ADJ. great, major, serious | absolute | chief, main | lawful, legal There are no legal impediments to their appealing against the decision.","VERB + IMPEDIMENT be, constitute, provide | remove The agreement is designed to remove impediments to trade between the two countries.","PREP. ~ to Their boycott of the talks constitutes a serious impediment to peace negotiations."]},"media":{"uk":"media/ldoce/hwd/bre/3/impediment0205.mp3","us":"media/ldoce/hwd/ame/7/impediment.mp3"},"examples":[{"en":"The level of inflation is a serious impediment to economic recovery.","cn":"通货膨胀是影响经济复苏的严重障碍。"},{"en":"a speech impediment","cn":"言语障碍"}],"oxford":{"phon":"ɪmˈpedɪmənt","pos":"noun","senses":[{"en":"something that delays or stops the progress of something","cn":"妨碍；阻碍；障碍","lab":"formal","ex":{"en":"The level of inflation is a serious impediment to economic recovery.","cn":"通货膨胀是影响经济复苏的严重障碍。"}},{"en":"a problem, for example a stammer, that makes it more difficult for somebody to speak, hear, etc.","cn":"（生理问题导致的）言语[听觉，行动]障碍","lab":"becoming old-fashioned","ex":{"en":"a speech impediment","cn":"言语障碍"}}]}},"impotent":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无能为力的;不起作用的","en":"If someone feels impotent, they feel that they have no power to influence people or events.","ex":{"en":"The aggression of a bully leaves people feeling hurt, angry and impotent","cn":"暴徒的侵犯令人们感到痛心、愤怒却又无能为力。"}},{"pos":"ADJ 形容词","cn":"阳痿的;性无能的","en":"If a man is impotent, he is unable to have sex normally, because his penis fails to get hard or stay hard."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unable to take effective action because you do not have enough power, strength, or control","cn":"无影响力的﹐无能为力的"},{"en":"a man who is impotent is unable to have sex because he cannot get an erection 〔","cn":"男子〕性无能的﹐阳痿的"}]},"vocab":{"pos":"adj","senses":[{"en":"Impotent means lacking power or authority. Captain Bligh was impotent in the face of Christian's mutiny. It also refers to a man's inability to achieve or maintain an erection. If a man is sterile, or unable to reproduce, he is also called impotent ."}]},"collocations":{"phrases":["VERBS be, feel, prove | remain | leave sb, make sb, render sb Companies are rendered impotent by all the rules and regulations.","ADV. completely, quite, totally | virtually | politically","PREP. against They were virtually impotent against the power of the large companies. 2 not capable of having sex","VERBS be | become | leave sb, make sb The operation left him impotent.","ADV. sexually"]},"media":{"uk":"media/ldoce/hwd/bre/5/impotent0205.mp3","us":"media/ldoce/hwd/ame/7/impotent.mp3"},"examples":[{"en":"Without the chairman's support, the committee is impotent.","cn":"没有主席的支持，委员会是无能为力的。"},{"en":"a feeling of impotence in the face of an apparently insoluble problem","cn":"面对显然无法解决的问题的无力感"}],"oxford":{"phon":"ˈɪmpətənt","pos":"adjective","senses":[{"en":"having no power to change things or to influence a situation","cn":"无能为力的；不起作用的","ex":{"en":"Without the chairman's support, the committee is impotent.","cn":"没有主席的支持，委员会是无能为力的。"}},{"en":"(of a man) unable to achieve an erection and therefore unable to have full sex","cn":"性无能的；阳痿的","ex":{"en":"The operation left him impotent.","cn":"手术让他变得性无能。"}}]}},"immune":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(对疾病)免疫的,有免疫力的","en":"If you are immune to a particular disease, you cannot be affected by it.","ex":{"en":"This blood test will show whether or not you're immune to the disease","cn":"这个血检会显示你是否对这种疾病具有免疫力。"}},{"pos":"ADJ 形容词","cn":"(反应等)免疫的，免疫系统的","en":"An immune response or reaction is a reaction by the body's immune system to something harmful that is affecting it.","ex":{"en":"It is hoped the procedure will trigger an immune response that will wipe out HIV-infected cells while leaving non-infected cells unharmed.","cn":"希望这一治疗会激发免疫反应,清除感染了艾滋病病毒的细胞，同时又不损伤未感染细胞。"}},{"pos":"ADJ 形容词","cn":"不受影响的","en":"If you are immune to something that happens or is done, you are not affected by it.","ex":{"en":"Whilst Marc did gradually harden himself to the poverty, he did not become immune to the sight of death","cn":"尽管马克逐渐对贫困现象无动于衷,但他对于死亡的惨象还是不免动容。"}},{"pos":"ADJ 形容词","cn":"免除的;豁免的","en":"Someone or something that is immune from a particular process or situation is able to escape it.","ex":{"en":"Members of the Bundestag are immune from prosecution for corruption","cn":"德国联邦议院的成员可免受贪腐罪的起诉。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is immune to a particular disease cannot catch it 〔","cn":"对某种疾病〕有免疫力的"},{"en":"the reaction of the body’s immune system to something that is harmful","cn":"免疫反应"},{"en":"not affected by something that happens or is done","cn":"不受影响的"}]},"vocab":{"pos":"adj n","senses":[{"en":"To be immune to something is to be resistant to it. If you had chickenpox as a child, you should be immune to it now."}]},"collocations":{"phrases":["VERBS be, seem | become | remain, stay | make sb The vaccination doesn't necessarily make you completely immune.","ADV. completely, totally","PREP. to Many people are immune to this disease. 2 not affected by sth","VERBS appear, be, prove, seem | become | remain","ADV. completely, entirely, quite, totally, wholly | by no means, far from Children are far from immune to the virus of cruelty that is laten","PREP. to She's quite immune to criticism."]},"media":{"uk":"media/ldoce/hwd/bre/9/immune0205.mp3","us":"media/ldoce/hwd/ame/e/immune.mp3"},"examples":[{"en":"You'll eventually become immune to criticism.","cn":"你终究会变得不在乎批评了。"},{"en":"Adults are often immune to German measles.","cn":"成人往往对风疹有免疫力。"}],"oxford":{"phon":"ɪˈmjuːn","pos":"adjective","senses":[{"en":"that cannot catch or be affected by a particular disease or illness","cn":"有免疫力","ex":{"en":"Adults are often immune to German measles.","cn":"成人往往对风疹有免疫力。"}},{"en":"not affected by something, especially something that you might expect to be harmful","cn":"不受影响","ex":{"en":"You'll eventually become immune to criticism.","cn":"你终有一日会不再在意批评。"}},{"en":"protected from something and therefore able to avoid it","cn":"受保护；免除；豁免","ex":{"en":"No one should be immune from prosecution.","cn":"任何人都不应免于被起诉。"}}]}},"improper":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"不正当的;非法的","en":"Improper activities are illegal or dishonest.","ex":{"en":"25 officers were investigated following allegations of improper conduct during the murder inquiry","cn":"25 名警察在被指控于调查谋杀案期间有非法行为之后受到调查。"}},{"pos":"ADJ 形容词","cn":"不合适的;不适当的","en":"Improper conditions or methods of treatment are not suitable or good enough for a particular purpose.","ex":{"en":"The improper use of medicine could lead to severe adverse reactions.","cn":"用药不当会产生严重的不良反应。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不成体统的;不得体的","en":"If you describe someone's behaviour as improper, you mean that it is rude or shocking.","ex":{"en":"He would never be improper, he is always the perfect gentleman.","cn":"他总是举止得体,一直是个完美的绅士。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"dishonest, illegal, or morally wrong","cn":"不诚实的﹔不合法的﹔不道德的"},{"en":"not sensible, right, or fair in a particular situation","cn":"不理智的﹔不合适的﹔不公平的"},{"en":"wrong or not correct","cn":"错误的﹐不正确的"}]},"vocab":{"pos":"adj","senses":[{"en":"Improper words and actions are inappropriate. They're not suited to the occasion or done in polite company. They’re just not proper!"}]},"collocations":{"phrases":["VERBS be, seem | consider sth, regard sth as, think sth She thought it quite improper for a woman to ride a motorbike.","ADV. highly, most | entirely, quite"]},"media":{"uk":"media/ldoce/hwd/bre/b/improper0205.mp3","us":"media/ldoce/hwd/ame/b/improper.mp3"},"examples":[{"en":"There was nothing improper about our relationship (= it did not involve sex).","cn":"我们的关系没有什么不正当的。"},{"en":"It would be improper to comment at this stage.","cn":"在这个阶段发表评论并不恰当。"}],"oxford":{"phon":"ɪmˈprɒpə(r)","pos":"adjective","senses":[{"en":"dishonest, or morally wrong","cn":"不诚实的；不正当的；不道德的","ex":{"en":"He had been indulging in improper business practices.","cn":"他一直参与不正当的商业活动。"}},{"en":"not right or appropriate for the situation","cn":"不合适的；不适当的；不得体的","ex":{"en":"It would be improper to comment at this stage.","cn":"在这个阶段发表评论并不恰当。"}},{"en":"wrong; not correct","cn":"错误的；不正确的","ex":{"en":"improper use of the drug","cn":"药物的误用"}}]}},"impervious":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无动于衷的;不受影响的","en":"If you are impervious to someone's actions, you are not affected or influenced by them.","ex":{"en":"She seems almost impervious to the criticism from all sides","cn":"对于来自各方的指责,她似乎无动于衷。"}},{"pos":"ADJ 形容词","cn":"防渗漏的;不能渗透的;不能穿过的","en":"Something that is impervious to water, heat, or a particular object is able to resist it or stop it passing through it.","ex":{"en":"The floorcovering you select will need to be impervious to water.","cn":"挑选的地板材料必须是防水的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not affected or influenced by something and seeming not to notice it","cn":"不受影响的﹔无动于衷的"},{"en":"not allowing anything to enter or pass through","cn":"不能进入的﹐不能穿过的"}]},"vocab":{"pos":"adj","senses":[{"en":"An impervious surface is one that can't be penetrated. The word is often followed by \"to,\" as in \"His steely personality made him impervious to jokes about his awful haircut.\""}]},"collocations":{"phrases":["VERBS appear, be, seem | become | remain","ADV. completely, quite, totally, wholly He was completely impervious to criticism. | almost, largely, virtually | apparently","PREP. to She was impervious to his charms."]},"media":{"uk":"media/ldoce/hwd/bre/4/impervious0205.mp3","us":"media/ldoce/hwd/ame/e/impervious.mp3"},"examples":[{"en":"impervious to criticism/pain","cn":"能忍受批评/疼痛的"},{"en":"an impervious rock/layer","cn":"不透水的岩石/地层"}],"oxford":{"phon":"ɪmˈpɜːviəs","pos":"adjective","senses":[{"en":"not affected or influenced by something","cn":"不受影响的","ex":{"en":"impervious to criticism/pain","cn":"能忍受批评／疼痛的"}},{"en":"not allowing a liquid or gas to pass through","cn":"不能渗透的；不透气的；不透水的","lab":"specialist","ex":{"en":"an impervious rock/layer","cn":"不透水的岩石／地层"}}]}},"import":{"collins":{"senses":[{"pos":"VERB 动词","cn":"进口;引进","en":"To import products or raw materials means to buy them from another country for use in your own country.","ex":{"en":"Britain last year spent nearly £5000 million more on importing food than selling abroad","cn":"去年英国的进口食品支出比其出口食品收入多出近50亿英镑。"}},{"pos":"N-COUNT 可数名词","cn":"进口商品;进口货物","en":"Imports are products or raw materials bought from another country for use in your own country.","ex":{"en":"...farmers protesting about cheap imports.","cn":"抗议进口廉价商品的农民"}},{"pos":"N-UNCOUNT 不可数名词","cn":"重要(性)","en":"The import of something is its importance.","ex":{"en":"Who leads Canada is also of some import to the rest of the world","cn":"谁领导加拿大对世界来讲也具有一定的重要性。"}},{"pos":"VERB 动词","cn":"导入","en":"If you import files or information into one type of software from another type, you open them in a format that can be used in the new software.","ex":{"en":"You can import files from Microsoft Word 5.1 or MacWrite II.","cn":"可以从 Microsoft Word 5.1 或 MacWrite II 程序导入文件。"}},{"pos":"N-SING 单数名词","cn":"意思;含意","en":"The import of something is its meaning, especially when the meaning is not clearly expressed.","ex":{"en":"I have already spoken about the import of his speech.","cn":"有关他的讲话的含意我刚刚已经谈过了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that is made or produced in large quantities, usually in order to be sold","cn":""},{"en":"things that are produced in order to be sold, especially for use in the home","cn":""},{"en":"a type of product or raw material that can be bought and sold – used especially about basic food products, metals, and fuels","cn":""}]},"vocab":{"pos":"1 v n 2 v 3 n v","senses":[{"en":"Imports are the products shipped into our country from other places. We import Japanese autos and export our pop music to Tokyo. Import also means to signify something. Is it of import to our economic security to have so many Japanese imports on our roads?"}]},"collocations":{"phrases":["ADV. directly | illegally, legally | specially","PREP. from The store's croissants are imported directly from France. | into These dogs are illegally imported into the country. | to goods t"]},"media":{"uk":"media/ldoce/hwd/bre/0/import_n0205.mp3","us":"media/ldoce/hwd/ame/c/l3import.mp3"},"examples":[{"en":"The report calls for a ban on the import of hazardous waste.","cn":"这篇报道呼吁禁止危险废弃物的进口。"},{"en":"It is difficult to understand the full import of this statement.","cn":"很难理解这份声明中的全部含意。"}],"oxford":{"phon":"ˈɪmpɔːt","pos":"noun","senses":[{"en":"a product or service that is brought into one country from another","cn":"进口品；输入的产品（或服务）","g":"[countable, usually plural]","ex":{"en":"food imports from abroad","cn":"从外国进口的食物"}},{"en":"the act of bringing a product or service into one country from another","cn":"（产品、劳务的）进口，输入，引进","g":"[uncountable, plural]","ex":{"en":"The report calls for a ban on the import of hazardous waste.","cn":"这份报告呼吁禁止进口危险废弃物。"}},{"en":"importance","cn":"重要性","g":"[uncountable]","lab":"formal","ex":{"en":"matters of great import","cn":"非常重要的事情"}},{"en":"the meaning of something, especially when it is not immediately clear","cn":"意思；含意","g":"[singular]","lab":"formal","ex":{"en":"It is difficult to understand the full import of this statement.","cn":"很难理解这份声明的全部含意。"}},{"en":"to bring a product, a service, an idea, etc. into one country from another","cn":"进口；输入；引进","ex":{"en":"The country has to import most of its raw materials.","cn":"这个国家大多数原料依赖进口。"},"pos":"verb"},{"en":"to get data from another program, changing its form so that the program you are using can read it","cn":"导入；输入；移入","lab":"computing","pos":"verb"}]}},"implicate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"使牵连其中;涉及","en":"To implicate someone means to show or claim that they were involved in something wrong or criminal.","ex":{"en":"Allegations had appeared in the press implicating the army and police in some of the killings","cn":"有关军方和警方与几起命案有牵连的指控出现在了新闻报道中。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to show or seem to show that someone is involved in something bad or illegal","cn":""},{"en":"use this about documents, tapes, photographs, statements etc that seem to show that someone is guilty of a crime","cn":""},{"en":"to make someone seem guilty of a crime","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"The verb implicate means \"to connect or involve in something.\" For example, your cousins might implicate you in the planning of a big party for your grandparents."}]},"collocations":{"phrases":["ADV. deeply, heavily, strongly These groups are very strongly implicated in the violence. | directly"]},"media":{"uk":"media/ldoce/hwd/bre/e/implicate0205.mp3","us":"media/ldoce/hwd/ame/1/implicate.mp3"},"examples":[{"en":"The results implicate poor hygiene as one cause of the outbreak.","cn":"这些结果说明卫生条件差是疾病爆发的一个原因。"},{"en":"He tried to avoid saying anything that would implicate him further.","cn":"他尽力避免说出任何会进一步牵连他的事情。"}],"oxford":{"phon":"ˈɪmplɪkeɪt","pos":"verb","senses":[{"en":"to show or suggest that somebody is involved in something bad or criminal","cn":"牵涉，涉及（某人）","ex":{"en":"He tried to avoid saying anything that would implicate him further.","cn":"他尽力避免说出任何会进一步牵连他的事情。"}},{"en":"to show or suggest that something is the cause of something bad","cn":"表明（或意指）…是起因","ex":{"en":"The results implicate poor hygiene as one cause of the outbreak.","cn":"这些结果说明卫生条件差是疾病暴发的一个原因。"}}]}},"impenetrable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不能穿过的;刺不进的;透不过的","en":"If you describe something such as a barrier or a forest as impenetrable, you mean that it is impossible or very difficult to get through.","ex":{"en":"...the Caucasus range, an almost impenetrable barrier between Europe and Asia.","cn":"高加索山脉,几乎难以穿越的欧亚屏障"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"费解的;难以理解的","en":"If you describe something such as a book or a theory as impenetrable, you are emphasizing that it is impossible or very difficult to understand.","ex":{"en":"His books are notoriously impenetrable.","cn":"他的书出了名的晦涩难懂。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"impossible to get through, see through, or get into","cn":"不能通过的﹔不能看透的﹔无法进入的"},{"en":"very difficult or impossible to understand","cn":"费解的﹔不可理解的"}]},"vocab":{"pos":"adj","senses":[{"en":"Impenetrable describes something that's impossible to get through. Whether it's a brick wall or a difficult reading passage, something impenetrable won't let you in."}]},"collocations":{"phrases":["VERBS appear, be, look, seem | become | find sth They found the jungle virtually impenetrable.","ADV. almost, nearly, virtually 2 impossible to understand","VERBS be, seem | become | remain | find sth","ADV. almost, virtually | somewhat I find his style somewhat impenetrable. | seemingly","PREP. to The language of this document would be impenetrable to anyone except a specialist."]},"media":{"uk":"media/ldoce/hwd/bre/d/impenetrable0205.mp3","us":"media/ldoce/hwd/ame/1/impenetrable.mp3"},"examples":[{"en":"Their jargon is impenetrable to an outsider.","cn":"他们的行话外人听不懂。"},{"en":"an impenetrable jungle","cn":"无法穿越的丛林"}],"oxford":{"phon":"ɪmˈpenɪtrəbl","pos":"adjective","senses":[{"en":"that cannot be entered, passed through or seen through","cn":"不可进入的；穿不过的；无法透视的","ex":{"en":"an impenetrable jungle","cn":"无法穿越的丛林"}},{"en":"impossible to understand","cn":"不可理解的；高深莫测的","ex":{"en":"an impenetrable mystery","cn":"不解之谜"}}]}},"impressionable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(通常指年轻人)易受影响的,无主见的,无判断力的","en":"Someone who is impressionable, usually a young person, is not very critical and is therefore easy to influence.","ex":{"en":"The law is intended to protect young and impressionable viewers.","cn":"该法律意图保护那些年轻且无判断力的电视观众。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is a pushover is very easy to persuade, and you can get them to do what you want them to do","cn":""},{"en":"to be someone who can be easily persuaded to give someone what they want, especially because you are too kind and sympathetic","cn":""},{"en":"someone who is naïve is so young or inexperienced that they are likely to be easily persuaded to believe something","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"Someone who is impressionable is easily influenced. An impressionable person can be greatly changed by his or her experiences — not always in a good way."}]},"collocations":{"phrases":["VERBS be, seem","ADV. highly, very He is in a highly impressionable state."]},"media":{"uk":"media/ldoce/hwd/bre/b/impressionable0205.mp3","us":"media/ldoce/hwd/ame/b/impressionable.mp3"},"examples":[{"en":"children at an impressionable age","cn":"处于易受外界影响的年龄的儿童"},{"en":"The kids are at an impressionable age .","cn":"这些儿童正处于易受影响的年龄。"}],"oxford":{"phon":"ɪmˈpreʃənəbl","pos":"adjective","senses":[{"en":"easily influenced or affected by somebody/something","cn":"易受影响的","ex":{"en":"children at an impressionable age","cn":"处于易受外界影响的年龄的儿童"}}]}},"impair":{"collins":{"senses":[{"pos":"VERB 动词","cn":"损害;妨碍;削弱","en":"If something impairs something such as an ability or the way something works, it damages it or makes it worse.","ex":{"en":"Consumption of alcohol impairs your ability to drive a car or operate machinery","cn":"饮酒会削弱你驾驶汽车或操控机器的能力。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to have a bad effect on someone or something","cn":""},{"en":"to harm something badly. Damage is more serious than harm","cn":""},{"en":"to be likely to harm someone or something","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"If you make bad decisions in the morning after drinking coffee, you might conclude that caffeine tends to impair your judgment. When you impair something, you damage it or make it work poorly."}]},"collocations":{"phrases":["ADV. dramatically, gravely, greatly, seriously, severely, significantly, substantially | directly factors which directly impair memory","PHRASES badly impaired Her sight is badly impaired. | hearing/mentally/visually impaired the problems faced by people who are hearing impair"]},"media":{"uk":"media/ldoce/hwd/bre/6/impair0205.mp3","us":"media/ldoce/hwd/ame/1/impair.mp3"},"examples":[{"en":"The illness had impaired his ability to think and concentrate.","cn":"这种疾病损害了他的思维能力和注意力。"}],"oxford":{"phon":"ɪmˈpeə(r)","pos":"verb","senses":[{"en":"to damage something or make something worse","cn":"损害；削弱","ex":{"en":"His age impaired his chances of finding a new job.","cn":"他的年龄削弱了他找到新工作的机会。"}}]}}});
